/* Tech 3D · Nivell 2 · unitat 6 «Mòduls» · guia del professorat (p6-1 … p6-4)
   Material propi de Numi. Classe de 60 minuts; mateix esquema que TGUIDE['r1-1']. Les diapositives «media» mostren el
   programa i el model 3D (TMEDIA.model); els programes porten els noms dels mòduls en català i en castellà ("ca|es"). */
Object.assign(TGUIDE, (() => {
  const ES = { arbre: 'árbol', fanal: 'farola', banc: 'banco', finestra: 'ventana', façana: 'fachada', edifici: 'edificio', tanca: 'valla', esglaó: 'peldaño', llargada: 'largo', alçada: 'altura', gruix: 'grosor', mida: 'tamaño', costat: 'lado', bloc: 'bloque', porta: 'puerta', amplada: 'ancho', font: 'fuente', filera: 'hilera', xemeneia: 'chimenea' };
  const CM = { 'fanal(alçada): pal de 3 mm i un llum a dalt': 'farola(altura): poste de 3 mm y una luz arriba', 'banc(llargada): seient, potes i respatller, centrat': 'banco(largo): asiento, patas y respaldo, centrado',
    'arbre(mida): tronc i copa; mida = alçada del tronc': 'árbol(tamaño): tronco y copa; tamaño = altura del tronco', '===== Biblioteca de la maqueta =====': '===== Biblioteca de la maqueta =====', "===== L'escena: la plaça =====": '===== La escena: la plaza =====',
    'porta(amplada, alçada): un marc en forma de U invertida': 'puerta(ancho, altura): un marco en forma de U invertida', 'edifici(pisos): bloc amb finestres i terrat': 'edificio(pisos): bloque con ventanas y azotea', 'la base de la illa': 'la base de la manzana',
    '1 · Paràmetres del barri': '1 · Parámetros del barrio', '2 · Mòduls': '2 · Módulos', "3 · L'escena": '3 · La escena' };
  const KES = { cub: 'cubo', cilindre: 'cilindro', mou: 'mueve', repeteix: 'repite', defineix: 'define', con: 'cono', tub: 'tubo', piramide: 'piramide' };
  const es = (s, kw) => s.split('\n').map(l => { const c = l.indexOf('//'); const code = c < 0 ? l : l.slice(0, c), rem = c < 0 ? null : l.slice(c + 2).trim();
    return code.replace(/[A-Za-zÀ-ÿ_·][A-Za-z0-9_À-ÿ·]*/g, w => ES[w] || (kw && KES[w]) || w) + (rem == null ? '' : '// ' + (CM[rem] ?? rem)); }).join('\n');
  const B = s => s + '|' + es(s);          // programa (l'app tradueix les paraules del llenguatge)
  const CK = s => s + '|' + es(s, true);   // codi per llegir a la diapositiva (també les paraules del llenguatge)
  const ARBRE = `defineix arbre() {\n  cilindre(4, 12)\n  mou(0, 0, 16) esfera(14)\n}`;
  const DEF3 = `${ARBRE}\narbre()\nmou(30, 0, 0) arbre()\nmou(60, 10, 0) arbre()`;
  const FANAL = `defineix fanal() {\n  cilindre(10, 2)\n  cilindre(3, 30)\n  mou(0, 0, 32) esfera(8)\n}`;
  const STREET = `${FANAL}\nrepeteix i de 0 a 3 {\n  mou(i * 30, 0, 0) fanal()\n}`;
  const CITY1 = `defineix arbre() {\n  cilindre(4, 10)\n  mou(0, 0, 8) con(16, 22)\n}\nrepeteix i de 0 a 3 {\n  mou(i * 25, 0, 0) arbre()\n}`;
  const CASAX = `defineix casa() {\n  cub(20, 20, 16)\n  mou(10, 10, 16) piramide(24, 24, 12)\n  mou(13, 4, 18) cub(4, 4, 12)\n}\ncasa()\nmou(35, 0, 0) casa()\nmou(70, 0, 0) casa()`;
  const BANCM = `defineix banc() {\n  mou(0, 0, 8) cub(30, 10, 3)\n  mou(2, 2, 0) cub(4, 6, 8)\n  mou(24, 2, 0) cub(4, 6, 8)\n  mou(0, 8, 11) cub(30, 2, 8)\n}\nbanc()\nmou(50, 0, 0) banc()`;
  const TORRE = `defineix torre(alçada, gruix) {\n  cilindre(gruix, alçada)\n  mou(0, 0, alçada) con(gruix + 6, 12)\n}`;
  const TORRES = `${TORRE}\ntorre(30, 14)\nmou(30, 0, 0) torre(50, 14)\nmou(60, 0, 0) torre(40, 22)`;
  const EDI = `defineix edifici(pisos) {\n  color("blau") cub(24, 20, pisos * 10)\n  repeteix p de 0 a (pisos - 1) {\n    repeteix f de 0 a 1 {\n      mou(4 + f * 10, -1, 3 + p * 10) color("groc") cub(6, 2, 5)\n    }\n  }\n}\nedifici(2)\nmou(34, 0, 0) edifici(4)\nmou(68, 0, 0) edifici(6)`;
  const TFAM = `${TORRE}\nrepeteix i de 0 a 4 {\n  mou(i * 25, 0, 0) torre(20 + i * 10, 12)\n}`;
  const TANCA = `defineix tanca(n, alçada) {\n  repeteix i de 0 a (n - 1) {\n    mou(i * 12, 0, 0) cub(4, 4, alçada)\n  }\n  mou(0, 1, alçada - 8) cub((n - 1) * 12 + 4, 2, 4)\n}\ntanca(5, 20)\nmou(0, 30, 0) tanca(8, 30)`;
  const SPIRAL = `defineix esglaó(llargada) {\n  cub(llargada, 10, 4)\n}\ncilindre(10, 76)\nrepeteix i de 0 a 11 {\n  mou(0, 0, i * 6) gira(0, 0, i * 30) mou(0, -5, 0) esglaó(30)\n}`;
  const LFANAL = `// fanal(alçada): pal de 3 mm i un llum a dalt\ndefineix fanal(alçada) {\n  cilindre(10, 2)\n  cilindre(3, alçada)\n  mou(0, 0, alçada + 2) esfera(8)\n}`;
  const LBANC = `// banc(llargada): seient, potes i respatller, centrat\ndefineix banc(llargada) {\n  mou(-llargada / 2, -5, 8) cub(llargada, 10, 3)\n  mou(-llargada / 2 + 2, -3, 0) cub(4, 6, 8)\n  mou(llargada / 2 - 6, -3, 0) cub(4, 6, 8)\n  mou(-llargada / 2, 3, 11) cub(llargada, 2, 8)\n}`;
  const LARBRE = `// arbre(mida): tronc i copa; mida = alçada del tronc\ndefineix arbre(mida) {\n  cilindre(mida / 4, mida)\n  mou(0, 0, mida) esfera(mida)\n}`;
  const PLACA = `// ===== Biblioteca de la maqueta =====\n${LFANAL}\n${LBANC}\n${LARBRE}\n// ===== L'escena: la plaça =====\nmou(-30, 0, 0) fanal(30)\nmou(30, 0, 0) fanal(30)\nbanc(36)\nmou(0, 30, 0) arbre(16)`;
  const PORTA = `// porta(amplada, alçada): un marc en forma de U invertida\ndefineix porta(amplada, alçada) {\n  cub(4, 6, alçada)\n  mou(amplada - 4, 0, 0) cub(4, 6, alçada)\n  mou(0, 0, alçada) cub(amplada, 6, 4)\n}`;
  const ARBRES3 = `${LARBRE}\narbre(8)\nmou(25, 0, 0) arbre(16)\nmou(60, 0, 0) arbre(24)`;
  const EDIF = `// edifici(pisos): bloc amb finestres i terrat\ndefineix edifici(pisos) {\n  cub(20, 20, pisos * 10)\n  repeteix p de 0 a (pisos - 1) {\n    mou(4, -1, 3 + p * 10) color("groc") cub(12, 2, 5)\n  }\n  mou(-1, -1, pisos * 10) color("gris") cub(22, 22, 2)\n}`;
  const EDIF1 = `${EDIF}\nedifici(2)\nmou(30, 0, 0) edifici(3)\nmou(60, 0, 0) edifici(5)`;
  const ROWC = `${EDIF}\nrepeteix i de 0 a 3 {\n  mou(i * 30, 0, 0) edifici(2 + i)\n}`;
  const BLOCK = `// la base de la illa\ncolor("gris") cub(120, 120, 3)\n${EDIF}\nrepeteix j de 0 a 2 {\n  repeteix i de 0 a 2 {\n    mou(10 + i * 40, 10 + j * 40, 3) edifici(1 + i + j)\n  }\n}`;
  const BLOCKN = `// 1 · Paràmetres del barri\nn = 3\n// 2 · Mòduls\n${EDIF}\n// 3 · L'escena\ncolor("gris") cub(n * 40, n * 40, 3)\nrepeteix j de 0 a (n - 1) {\n  repeteix i de 0 a (n - 1) {\n    mou(10 + i * 40, 10 + j * 40, 3) edifici(1 + i + j)\n  }\n}`;
  return {
  /* ---------- Sessió 1 · Definir un mòdul ---------- */
  'p6-1': {
    obj: ["L'alumne/a defineix un mòdul sense paràmetres amb «defineix» i explica que la definició sola no construeix res.|El alumno/a define un módulo sin parámetros con «define» y explica que la definición sola no construye nada.",
      "L'alumne/a crida un mòdul diverses vegades i el col·loca amb mou, també des d'un bucle.|El alumno/a llama a un módulo varias veces y lo coloca con mueve, también desde un bucle.",
      "L'alumne/a reorganitza codi repetit en un mòdul (refactoritzar) sense canviar el resultat.|El alumno/a reorganiza código repetido en un módulo (refactorizar) sin cambiar el resultado.",
      "L'alumne/a localitza si un error és dins de la definició (afecta totes les còpies) o en una crida (afecta una còpia).|El alumno/a localiza si un error está dentro de la definición (afecta a todas las copias) o en una llamada (afecta a una copia)."],
    comp: ["Pensament computacional: abstracció i descomposició (definir peces reutilitzables)|Pensamiento computacional: abstracción y descomposición (definir piezas reutilizables)",
      "Tecnologia i digitalització: CAD 3D modular per a maquetes i prototips|Tecnología y digitalización: CAD 3D modular para maquetas y prototipos",
      "Competència digital: bones pràctiques de programació (no repetir codi, noms clars)|Competencia digital: buenas prácticas de programación (no repetir código, nombres claros)",
      "Matemàtiques: coordenades i translacions d'una figura composta|Matemáticas: coordenadas y traslaciones de una figura compuesta"],
    vocab: [["Mòdul|Módulo", "Un grup d'instruccions amb nom que es pot fer servir moltes vegades (a altres llenguatges, una funció).|Un grupo de instrucciones con nombre que se puede usar muchas veces (en otros lenguajes, una función)."],
      ["Definició|Definición", "On s'escriu què fa el mòdul: defineix nom() { … }.|Donde se escribe qué hace el módulo: define nombre() { … }."],
      ["Crida|Llamada", "La instrucció que fa servir el mòdul: nom(). Cada crida en fa una còpia.|La instrucción que usa el módulo: nombre(). Cada llamada hace una copia."],
      ["Reutilitzar|Reutilizar", "Fer servir el mateix codi diverses vegades sense copiar-lo.|Usar el mismo código varias veces sin copiarlo."],
      ["Refactoritzar|Refactorizar", "Reorganitzar un programa perquè sigui més clar sense canviar el que fa.|Reorganizar un programa para que sea más claro sin cambiar lo que hace."],
      ["Maqueta|Maqueta", "Model a escala d'un edifici, un barri o un objecte.|Modelo a escala de un edificio, un barrio o un objeto."]],
    mat: { aula: ["Un ordinador per alumne/a amb Numi Tech obert a la sessió «Definir un mòdul»|Un ordenador por alumno/a con Numi Tech abierto en la sesión «Definir un módulo»", "Projector i la presentació de la sessió|Proyector y la presentación de la sesión", "Paper quadriculat i llapis per parella|Papel cuadriculado y lápiz por pareja"],
      imprimir: ["Fitxa: la fàbrica de segells|Ficha: la fábrica de sellos"],
      prep: ["Imprimir la fitxa (una per parella).|Imprimir la ficha (una por pareja).", "Provar el repte dels dos bancs: cal embolcallar les 4 primeres línies i esborrar les altres 4.|Probar el reto de los dos bancos: hay que envolver las 4 primeras líneas y borrar las otras 4.", "Si en teniu, portar fotos d'una maqueta d'arquitectura o d'urbanisme.|Si las tenéis, traer fotos de una maqueta de arquitectura o de urbanismo."] },
    plan: [
      { min: 5, t: "L'encàrrec de la maqueta|El encargo de la maqueta", fase: 'inici', fa: "Presenta l'encàrrec de l'Ajuntament: 40 fanals, 25 bancs, 60 arbres… Recorda el bucle dels arbres i fes notar que el tronc i la copa sempre van junts: són una peça que es repeteix.|Presenta el encargo del Ayuntamiento: 40 farolas, 25 bancos, 60 árboles… Recuerda el bucle de los árboles y haz notar que el tronco y la copa siempre van juntos: son una pieza que se repite.",
        diu: ["Quantes línies faria el programa si escrivíssim els 40 fanals un per un?|¿Cuántas líneas haría el programa si escribiéramos las 40 farolas una por una?"], slides: ['s1', 's2'], app: "Encara no: pantalles abaixades.|Todavía no: pantallas bajadas.", org: "Tot el grup|Todo el grupo" },
      { min: 12, t: "Definir i cridar|Definir y llamar", fase: 'teoria', fa: "Explica el mòdul com un segell: una definició i moltes crides. Llegiu junts el mòdul arbre i les tres crides, després el fanal dins d'un bucle. Mostra què passa si no hi ha cap crida (placa buida) i com un canvi a la definició canvia totes les còpies.|Explica el módulo como un sello: una definición y muchas llamadas. Leed juntos el módulo árbol y las tres llamadas, después la farola dentro de un bucle. Muestra qué pasa si no hay ninguna llamada (placa vacía) y cómo un cambio en la definición cambia todas las copias.",
        diu: ["Si esborro les crides, què queda a la placa?|Si borro las llamadas, ¿qué queda en la placa?", "Si l'arbre ha de ser un con, quantes línies canvio?|Si el árbol tiene que ser un cono, ¿cuántas líneas cambio?"], slides: ['s3', 's4', 's5', 's6', 's7'], app: "Encara no: tota l'atenció a la projecció.|Todavía no: toda la atención en la proyección.", org: "Tot el grup|Todo el grupo" },
      { min: 10, t: "La fàbrica de segells|La fábrica de sellos", fase: 'desconnectat', fa: "Per parelles: una persona escriu la definició de casa() a la fitxa i l'altra dibuixa les crides al paper quadriculat. Després canvia la definició (porta) i comparen quants canvis cal fer al paper i quants al codi.|Por parejas: una persona escribe la definición de casa() en la ficha y la otra dibuja las llamadas en el papel cuadriculado. Después cambia la definición (puerta) y comparan cuántos cambios hay que hacer en el papel y cuántos en el código.",
        diu: ["Quantes cases heu hagut de redibuixar? I al codi, quantes línies canviaríeu?|¿Cuántas casas habéis tenido que redibujar? ¿Y en el código, cuántas líneas cambiaríais?"], slides: ['s8'], app: "Encara no: fitxa i paper quadriculat.|Todavía no: ficha y papel cuadriculado.", org: "Per parelles|Por parejas" },
      { min: 22, t: "A l'ordinador: fanals, bancs i cases|En el ordenador: farolas, bancos y casas", fase: 'ordinador', fa: "Fan l'app: predicció, dos errors (un dins del mòdul i un en una crida) i els reptes: cridar el fanal, convertir els dos bancs en un mòdul, una fila d'arbres amb bucle i la xemeneia de les cases. Al repte dels bancs, insisteix que el resultat ha de quedar igual: això és refactoritzar.|Hacen la app: predicción, dos errores (uno dentro del módulo y otro en una llamada) y los retos: llamar a la farola, convertir los dos bancos en un módulo, una fila de árboles con bucle y la chimenea de las casas. En el reto de los bancos, insiste en que el resultado tiene que quedar igual: eso es refactorizar.",
        diu: ["L'error afecta tots els fanals o només un? On el buscaràs?|¿El error afecta a todas las farolas o solo a una? ¿Dónde lo buscarás?", "Has tocat les crides per posar la xemeneia?|¿Has tocado las llamadas para poner la chimenea?"], slides: ['s9', 's10', 's11', 's12'], app: "Sessió «Definir un mòdul», fins al disseny lliure.|Sesión «Definir un módulo», hasta el diseño libre.", org: "Individual|Individual" },
      { min: 6, t: "El meu carrer|Mi calle", fase: 'crea', fa: "Disseny lliure: un mòdul propi (arbre, fanal, banc, paperera…) fet servir moltes vegades per fer un carrer. Es desa a «Projectes».|Diseño libre: un módulo propio (árbol, farola, banco, papelera…) usado muchas veces para hacer una calle. Se guarda en «Proyectos».",
        diu: ["Quin nom has donat al teu mòdul? S'entén què és sense obrir-lo?|¿Qué nombre has dado a tu módulo? ¿Se entiende qué es sin abrirlo?"], slides: ['s13'], app: "Pas «El carrer de la maqueta».|Paso «La calle de la maqueta».", org: "Individual|Individual" },
      { min: 5, t: "Tancament|Cierre", fase: 'tancament', fa: "Repassa les idees clau i el tiquet de sortida.|Repasa las ideas clave y el ticket de salida.", diu: ["Què passa si defineixes un mòdul però no el crides?|¿Qué pasa si defines un módulo pero no lo llamas?"], slides: ['s14', 's15'], app: "Les últimes preguntes i «Com t'ha anat?».|Las últimas preguntas y «¿Cómo te ha ido?».", org: "Tot el grup|Todo el grupo" }
    ],
    errors: [["Defineix el mòdul i espera que surti alguna cosa sense cridar-lo.|Define el módulo y espera que salga algo sin llamarlo.", "Recorda-li que la definició és la recepta guardada: cal almenys una crida nom() perquè es construeixi.|Recuérdale que la definición es la receta guardada: hace falta al menos una llamada nombre() para que se construya."],
      ["Posa el mou dins de la definició i tots els arbres surten al mateix lloc desplaçat.|Pone el mueve dentro de la definición y todos los árboles salen en el mismo sitio desplazado.", "Dins del mòdul, la peça es dibuixa a l'origen. On va cada còpia ho decideix el mou de davant de cada crida.|Dentro del módulo, la pieza se dibuja en el origen. Dónde va cada copia lo decide el mueve delante de cada llamada."],
      ["Escriu el nom diferent a la definició i a la crida (fanal / Fanal / fanals).|Escribe el nombre distinto en la definición y en la llamada (farola / Farola / farolas).", "El taller avisa «no hi ha cap mòdul que es digui…» i proposa el nom més semblant. Que copiï el nom exacte de la definició.|El taller avisa «no hay ningún módulo que se llame…» y propone el nombre más parecido. Que copie el nombre exacto de la definición."]],
    diff: { mes: "Fer el repte ⭐ de la façana (un mòdul que en crida un altre dins de dos bucles) i, després, un mòdul carrer() que faci servir fanal() i arbre().|Hacer el reto ⭐ de la fachada (un módulo que llama a otro dentro de dos bucles) y, después, un módulo calle() que use farola() y árbol().",
      menys: "Treballar amb blocs, amb el bloc «usa el mòdul» de la paleta. Al repte dels bancs, donar-li ja escrita la línia defineix banc() { i la clau de tancar.|Trabajar con bloques, con el bloque «usa el módulo» de la paleta. En el reto de los bancos, darle ya escrita la línea define banco() { y la llave de cerrar." },
    aval: { ticket: ["Què passa si defineixes un mòdul i no el crides?|¿Qué pasa si defines un módulo y no lo llamas?", "Escriu la crida per posar el mòdul arbre() a x = 40.|Escribe la llamada para poner el módulo árbol() en x = 40."],
      rubric: [["Definir i cridar|Definir y llamar", "Defineix el mòdul a l'origen i el col·loca amb mou a cada crida.|Define el módulo en el origen y lo coloca con mueve en cada llamada.", "Ho fa amb ajuda o barreja la posició dins de la definició.|Lo hace con ayuda o mezcla la posición dentro de la definición."],
        ["Refactoritzar|Refactorizar", "Converteix codi repetit en un mòdul i el resultat no canvia.|Convierte código repetido en un módulo y el resultado no cambia.", "Fa el mòdul però deixa còpies o canvia el resultat.|Hace el módulo pero deja copias o cambia el resultado."],
        ["Depurar|Depurar", "Distingeix errors de la definició i de les crides.|Distingue errores de la definición y de las llamadas.", "Troba l'error provant línia per línia.|Encuentra el error probando línea por línea."]] },
    casa: "Busca al teu barri un element que es repeteixi molt (fanals, bancs, papereres, arbres…). Dibuixa'l i escriu com seria el seu mòdul: nom i peces amb mides aproximades.|Busca en tu barrio un elemento que se repita mucho (farolas, bancos, papeleras, árboles…). Dibújalo y escribe cómo sería su módulo: nombre y piezas con medidas aproximadas.",
    intro: "Els mòduls són l'abstracció més potent del curs: posar nom a un grup d'instruccions i fer-lo servir com una peça nova del llenguatge. És el mateix concepte que les funcions d'altres llenguatges i el module d'OpenSCAD.|Los módulos son la abstracción más potente del curso: poner nombre a un grupo de instrucciones y usarlo como una pieza nueva del lenguaje. Es el mismo concepto que las funciones de otros lenguajes y el module de OpenSCAD.",
    claus: ["defineix nom() { … } guarda la recepta; nom() la construeix.|define nombre() { … } guarda la receta; nombre() la construye.", "Sense crides, la definició no fa res.|Sin llamadas, la definición no hace nada.", "El mou de davant de cada crida col·loca la còpia; dins del mòdul, la peça és a l'origen.|El mueve delante de cada llamada coloca la copia; dentro del módulo, la pieza está en el origen.", "Un canvi a la definició canvia totes les còpies.|Un cambio en la definición cambia todas las copias."],
    prev: ["Haver fet la unitat de bucles (repeteix).|Haber hecho la unidad de bucles (repite).", "Conèixer mou i les formes bàsiques.|Conocer mueve y las formas básicas.", "Saber llegir coordenades x, y, z.|Saber leer coordenadas x, y, z."],
    faq: [["És el mateix un mòdul que un bucle?|¿Es lo mismo un módulo que un bucle?", "No: el bucle repeteix ara mateix, al mateix lloc del programa; el mòdul guarda una peça amb nom que pots fer servir quan vulguis i on vulguis. Sovint es fan servir junts: un bucle que crida un mòdul.|No: el bucle repite ahora mismo, en el mismo sitio del programa; el módulo guarda una pieza con nombre que puedes usar cuando quieras y donde quieras. A menudo se usan juntos: un bucle que llama a un módulo."],
      ["On s'ha d'escriure la definició?|¿Dónde hay que escribir la definición?", "On vulgueu: el taller llegeix primer totes les definicions. Per costum, es posen al principi, abans de l'escena.|Donde queráis: el taller lee primero todas las definiciones. Por costumbre, se ponen al principio, antes de la escena."],
      ["Un mòdul pot cridar un altre mòdul?|¿Un módulo puede llamar a otro módulo?", "Sí, i és molt útil (la façana crida la finestra). El que no pot fer és cridar-se a si mateix sense fi: el taller ho atura i avisa.|Sí, y es muy útil (la fachada llama a la ventana). Lo que no puede hacer es llamarse a sí mismo sin fin: el taller lo para y avisa."]],
    tec: [["El bloc «usa el mòdul» crida un mòdul que no volia.|El bloque «usa el módulo» llama a un módulo que no quería.", "El bloc crida el primer mòdul del programa. Toqueu el nom del bloc per triar un altre mòdul de la llista.|El bloque llama al primer módulo del programa. Tocad el nombre del bloque para elegir otro módulo de la lista."],
      ["Surt «no hi ha cap mòdul que es digui…».|Sale «no hay ningún módulo que se llame…».", "El nom de la crida no és exactament el de la definició (majúscules, accents, plural). El taller suggereix el nom més semblant.|El nombre de la llamada no es exactamente el de la definición (mayúsculas, acentos, plural). El taller sugiere el nombre más parecido."],
      ["En tocar una peça al 3D se selecciona la crida, no la definició.|Al tocar una pieza en el 3D se selecciona la llamada, no la definición.", "És normal: la peça surt d'aquella crida. Per canviar-la, editeu el mòdul a la definició.|Es normal: la pieza sale de esa llamada. Para cambiarla, editad el módulo en la definición."]],
    extra: ["Fer un mòdul semàfor() i posar-ne un a cada cantonada amb un bucle i gira.|Hacer un módulo semáforo() y poner uno en cada esquina con un bucle y gira.", "Exportar el carrer a .scad i trobar-hi els module d'OpenSCAD.|Exportar la calle a .scad y encontrar los module de OpenSCAD.", "Fer un mòdul banc_doble() que cridi dues vegades banc().|Hacer un módulo banco_doble() que llame dos veces a banco()."],
    trans: ["Sessió següent: mòduls amb paràmetres (torres de totes les mides).|Sesión siguiente: módulos con parámetros (torres de todos los tamaños).", "Ciències socials: l'urbanisme i el mobiliari urbà del barri.|Ciencias sociales: el urbanismo y el mobiliario urbano del barrio."],
    slides: [
      { id: 's1', k: 'portada', t: 'Definir un mòdul|Definir un módulo', x: 'Les teves pròpies peces|Tus propias piezas', nota: "Presenta l'encàrrec de la maqueta del barri del futur.|Presenta el encargo de la maqueta del barrio del futuro." },
      { id: 's2', k: 'pregunta', t: '40 fanals?|¿40 farolas?', x: "Cada fanal té 3 peces. Quantes línies faria el programa? Què es repeteix?|Cada farola tiene 3 piezas. ¿Cuántas líneas haría el programa? ¿Qué se repite?", code: CK(`cilindre(10, 2)\ncilindre(3, 30)\nmou(0, 0, 32) esfera(8)`), nota: "120 línies només per als fanals! Busquem la idea de «posar-li un nom».|¡120 líneas solo para las farolas! Buscamos la idea de «ponerle un nombre»." },
      { id: 's3', k: 'anim', t: 'Una peça amb nom|Una pieza con nombre', anim: 'p6def', nota: "Una definició (la recepta) i tres crides (tres còpies).|Una definición (la receta) y tres llamadas (tres copias)." },
      { id: 's4', k: 'media', t: 'defineix i crida|define y llama', media: { k: 'model', prog: B(DEF3) }, nota: "Dins del mòdul, l'arbre és a l'origen; el mou de cada crida el col·loca.|Dentro del módulo, el árbol está en el origen; el mueve de cada llamada lo coloca." },
      { id: 's5', k: 'media', t: 'Mòdul + bucle|Módulo + bucle', media: { k: 'model', prog: B(STREET) }, nota: "4 fanals amb una sola línia dins del bucle.|4 farolas con una sola línea dentro del bucle." },
      { id: 's6', k: 'concepte', t: 'Definir no és construir|Definir no es construir', punts: ["Només definició → placa buida.|Solo definición → placa vacía.", "Definició + crida → una peça.|Definición + llamada → una pieza.", "La definició pot anar al principi o al final.|La definición puede ir al principio o al final."], code: CK(FANAL), nota: "Pregunta: què surt si el programa és només això?|Pregunta: ¿qué sale si el programa es solo esto?" },
      { id: 's7', k: 'media', t: 'Canvies una vegada, canvia tot|Cambias una vez, cambia todo', media: { k: 'model', prog: B(CITY1) }, nota: "Hem canviat la copa per un con a la definició: els 4 arbres canvien.|Hemos cambiado la copa por un cono en la definición: los 4 árboles cambian." },
      { id: 's8', k: 'activitat', t: 'La fàbrica de segells|La fábrica de sellos', timer: 8, punts: ["Definiu casa() a la fitxa.|Definid casa() en la ficha.", "Dibuixeu les crides al paper.|Dibujad las llamadas en el papel.", "Canvieu la definició: quantes coses heu de redibuixar?|Cambiad la definición: ¿cuántas cosas tenéis que redibujar?"], nota: "Per parelles. La comparació paper / codi és la clau.|Por parejas. La comparación papel / código es la clave." },
      { id: 's9', k: 'pregunta', t: 'Prediu: on queden els arbres?|Predice: ¿dónde quedan los árboles?', code: CK(`${ARBRE}\narbre()\nmou(25, 0, 0) arbre()\nmou(0, 25, 0) arbre()`), nota: "Fan una L: origen, 25 en x i 25 en y.|Forman una L: origen, 25 en x y 25 en y." },
      { id: 's10', k: 'repte', t: "A l'ordinador|En el ordenador", punts: ["Troba l'error: dins del mòdul o a la crida?|Encuentra el error: ¿dentro del módulo o en la llamada?", "Crida el fanal i fes el mòdul dels bancs.|Llama a la farola y haz el módulo de los bancos.", "Fila d'arbres i xemeneies.|Fila de árboles y chimeneas."], nota: "Si l'error surt a totes les còpies, és dins de la definició.|Si el error sale en todas las copias, está dentro de la definición." },
      { id: 's11', k: 'media', t: 'Els dos bancs amb un mòdul|Los dos bancos con un módulo', media: { k: 'model', prog: B(BANCM) }, nota: "Mateix resultat, menys línies i més fàcil de canviar: refactoritzar.|Mismo resultado, menos líneas y más fácil de cambiar: refactorizar." },
      { id: 's12', k: 'media', t: 'Xemeneies per a totes|Chimeneas para todas', media: { k: 'model', prog: B(CASAX) }, nota: "Una línia nova dins de la definició; les crides no es toquen.|Una línea nueva dentro de la definición; las llamadas no se tocan." },
      { id: 's13', k: 'repte', t: 'El meu carrer|Mi calle', punts: ["Un mòdul teu amb nom clar.|Un módulo tuyo con nombre claro.", "Almenys 3 còpies.|Al menos 3 copias.", "Tot a la placa.|Todo en la placa."], nota: "Idees: paperera, banc, fanal, arbre, parada de bus.|Ideas: papelera, banco, farola, árbol, parada de bus." },
      { id: 's14', k: 'resum', t: 'Avui hem après…|Hoy hemos aprendido…', punts: ["defineix guarda la recepta; nom() la construeix.|define guarda la receta; nombre() la construye.", "El mou de cada crida col·loca la còpia.|El mueve de cada llamada coloca la copia.", "Un canvi a la definició ho canvia tot.|Un cambio en la definición lo cambia todo."], nota: "Llegiu-ho junts.|Leedlo juntos." },
      { id: 's15', k: 'tiquet', t: 'Tiquet de sortida|Ticket de salida', punts: ["Què passa si no crides el mòdul?|¿Qué pasa si no llamas al módulo?", "Escriu la crida per posar arbre() a x = 40.|Escribe la llamada para poner árbol() en x = 40."], nota: "En un paper, abans de sortir.|En un papel, antes de salir." }
    ],
    print: [{ id: 'p1', t: 'Fitxa: la fàbrica de segells|Ficha: la fábrica de sellos', k: 'fitxa', intro: "Un mòdul és com un segell: es dissenya una vegada i es fa servir moltes. Cada casella del paper és una unitat.|Un módulo es como un sello: se diseña una vez y se usa muchas. Cada casilla del papel es una unidad.",
      items: [{ q: "Defineix el mòdul: <code>casa() = quadrat de 2 × 2 caselles i un triangle a sobre</code>. Dibuixa'l a l'origen (cantonada de baix a l'esquerra).|Define el módulo: <code>casa() = cuadrado de 2 × 2 casillas y un triángulo encima</code>. Dibújalo en el origen (esquina de abajo a la izquierda).", big: true, sol: "Un quadrat de 2 × 2 amb la cantonada a (0, 0) i un triangle de base 2 a sobre.|Un cuadrado de 2 × 2 con la esquina en (0, 0) y un triángulo de base 2 encima." },
        { q: "Dibuixa les crides: <code>casa() · mou(4, 0) casa() · mou(8, 2) casa()</code>.|Dibuja las llamadas: <code>casa() · mueve(4, 0) casa() · mueve(8, 2) casa()</code>.", big: true, sol: "Tres cases: a (0, 0), a (4, 0) i a (8, 2).|Tres casas: en (0, 0), en (4, 0) y en (8, 2)." },
        { q: "Ara totes les cases han de tenir porta. Quantes coses redibuixes al paper? Quantes línies canviaries al codi?|Ahora todas las casas tienen que tener puerta. ¿Cuántas cosas redibujas en el papel? ¿Cuántas líneas cambiarías en el código?", sol: "Al paper, 3 portes (una per casa). Al codi, una sola línia dins de la definició.|En el papel, 3 puertas (una por casa). En el código, una sola línea dentro de la definición." },
        { q: "Escriu un bucle que posi 5 cases en fila, una cada 3 caselles.|Escribe un bucle que ponga 5 casas en fila, una cada 3 casillas.", sol: "repeteix i de 0 a 4 { mou(i * 3, 0) casa() }|repite i de 0 a 4 { mueve(i * 3, 0) casa() }" }] }]
  },
  /* ---------- Sessió 2 · Mòduls amb paràmetres ---------- */
  'p6-2': {
    obj: ["L'alumne/a defineix mòduls amb un o més paràmetres i els fa servir dins del mòdul com a variables.|El alumno/a define módulos con uno o más parámetros y los usa dentro del módulo como variables.",
      "L'alumne/a crida un mòdul amb els valors en l'ordre correcte i explica què passa si s'intercanvien.|El alumno/a llama a un módulo con los valores en el orden correcto y explica qué pasa si se intercambian.",
      "L'alumne/a combina paràmetres, càlculs i bucles dins d'un mòdul (edificis amb un nombre variable de pisos).|El alumno/a combina parámetros, cálculos y bucles dentro de un módulo (edificios con un número variable de pisos).",
      "L'alumne/a crida un mòdul paramètric des d'un bucle per fer una família de peces.|El alumno/a llama a un módulo paramétrico desde un bucle para hacer una familia de piezas."],
    comp: ["Pensament computacional: generalització i paràmetres (una solució per a tota una família de problemes)|Pensamiento computacional: generalización y parámetros (una solución para toda una familia de problemas)",
      "Matemàtiques: expressions algebraiques amb diverses variables i substitució de valors|Matemáticas: expresiones algebraicas con varias variables y sustitución de valores",
      "Tecnologia i digitalització: disseny paramètric de components (CAD 3D)|Tecnología y digitalización: diseño paramétrico de componentes (CAD 3D)",
      "Aprendre a aprendre: predir el resultat d'una crida i comprovar-lo|Aprender a aprender: predecir el resultado de una llamada y comprobarlo"],
    vocab: [["Paràmetre|Parámetro", "Un nom a la definició del mòdul que rep un valor a cada crida: torre(alçada).|Un nombre en la definición del módulo que recibe un valor en cada llamada: torre(altura)."],
      ["Argument (valor)|Argumento (valor)", "El número que es posa a la crida: torre(40).|El número que se pone en la llamada: torre(40)."],
      ["Àmbit|Ámbito", "On existeix un nom: els paràmetres només existeixen dins del seu mòdul.|Dónde existe un nombre: los parámetros solo existen dentro de su módulo."],
      ["Família de peces|Familia de piezas", "Peces amb la mateixa forma i mides diferents, fetes amb el mateix mòdul.|Piezas con la misma forma y medidas distintas, hechas con el mismo módulo."],
      ["Ordre dels arguments|Orden de los argumentos", "El primer valor va al primer paràmetre, el segon al segon…|El primer valor va al primer parámetro, el segundo al segundo…"]],
    mat: { aula: ["Un ordinador per alumne/a amb Numi Tech obert a la sessió «Mòduls amb paràmetres»|Un ordenador por alumno/a con Numi Tech abierto en la sesión «Módulos con parámetros»", "Projector i la presentació de la sessió|Proyector y la presentación de la sesión", "Paper quadriculat i llapis per parella|Papel cuadriculado y lápiz por pareja"],
      imprimir: ["Fitxa: receptes amb buits|Ficha: recetas con huecos"],
      prep: ["Imprimir la fitxa (una per parella).|Imprimir la ficha (una por pareja).", "Provar el repte de les finestres de l'edifici: el bucle va de 0 a (pisos - 1).|Probar el reto de las ventanas del edificio: el bucle va de 0 a (pisos - 1).", "Pensar exemples quotidians de «receptes amb buits» (una recepta per a n persones, una plantilla).|Pensar ejemplos cotidianos de «recetas con huecos» (una receta para n personas, una plantilla)."] },
    plan: [
      { min: 5, t: "Totes les mides|Todos los tamaños", fase: 'inici', fa: "Recorda definir i cridar. Planteja el nou problema: torres altes i baixes, edificis de 2, 4 i 7 pisos. Fem un mòdul per a cada mida?|Recuerda definir y llamar. Plantea el nuevo problema: torres altas y bajas, edificios de 2, 4 y 7 pisos. ¿Hacemos un módulo para cada tamaño?",
        diu: ["Què tenen en comú una torre de 20 mm i una de 60? Què canvia?|¿Qué tienen en común una torre de 20 mm y una de 60? ¿Qué cambia?"], slides: ['s1', 's2'], app: "Encara no: pantalles abaixades.|Todavía no: pantallas bajadas.", org: "Tot el grup|Todo el grupo" },
      { min: 12, t: "Paràmetres|Parámetros", fase: 'teoria', fa: "Explica el paràmetre com un buit de la recepta amb l'animació de les torres. Llegiu torre(alçada, gruix) i les tres crides; mostra què passa en girar els valors. Acaba amb l'edifici (paràmetre dins d'un càlcul i d'un bucle) i amb la família de torres cridada des d'un bucle.|Explica el parámetro como un hueco de la receta con la animación de las torres. Leed torre(altura, grosor) y las tres llamadas; muestra qué pasa al girar los valores. Acaba con el edificio (parámetro dentro de un cálculo y de un bucle) y con la familia de torres llamada desde un bucle.",
        diu: ["A torre(40, 16), quin número és l'alçada?|En torre(40, 16), ¿qué número es la altura?", "Quantes files de finestres té edifici(4)?|¿Cuántas filas de ventanas tiene edificio(4)?"], slides: ['s3', 's4', 's5', 's6', 's7'], app: "Encara no: tota l'atenció a la projecció.|Todavía no: toda la atención en la proyección.", org: "Tot el grup|Todo el grupo" },
      { min: 10, t: "Receptes amb buits|Recetas con huecos", fase: 'desconnectat', fa: "Per parelles amb la fitxa: una persona diu crides de casa(amplada, alçada) i l'altra les dibuixa. Al final, una crida amb els valors girats per veure què canvia. Després escriuen el seu propi mòdul amb un paràmetre.|Por parejas con la ficha: una persona dice llamadas de casa(ancho, altura) y la otra las dibuja. Al final, una llamada con los valores girados para ver qué cambia. Después escriben su propio módulo con un parámetro.",
        diu: ["Digues en veu alta quin valor va a cada paràmetre.|Di en voz alta qué valor va a cada parámetro."], slides: ['s8'], app: "Encara no: fitxa i paper quadriculat.|Todavía no: ficha y papel cuadriculado.", org: "Per parelles|Por parejas" },
      { min: 22, t: "A l'ordinador: torres, tanques i edificis|En el ordenador: torres, vallas y edificios", fase: 'ordinador', fa: "Fan l'app: prediccions, dos errors (un bucle de més i uns valors girats) i els reptes: afegir el paràmetre a la torre, la tanca amb dos paràmetres, les finestres de l'edifici i la família de torres amb un bucle. Passa per les taules a la tanca: que expliquin d'on surt la llargada de la travessa.|Hacen la app: predicciones, dos errores (un bucle de más y unos valores girados) y los retos: añadir el parámetro a la torre, la valla con dos parámetros, las ventanas del edificio y la familia de torres con un bucle. Pasa por las mesas en la valla: que expliquen de dónde sale la longitud del travesaño.",
        diu: ["Què val alçada dins del mòdul quan crides torre(45)?|¿Qué vale altura dentro del módulo cuando llamas a torre(45)?", "Per què la travessa fa (n − 1) × 12 + 4?|¿Por qué el travesaño mide (n − 1) × 12 + 4?"], slides: ['s9', 's10', 's11', 's12'], app: "Sessió «Mòduls amb paràmetres», fins al disseny lliure.|Sesión «Módulos con parámetros», hasta el diseño libre.", org: "Individual|Individual" },
      { min: 6, t: "La meva família de peces|Mi familia de piezas", fase: 'crea', fa: "Disseny lliure: un mòdul amb almenys un paràmetre cridat 3 vegades o més amb valors diferents. Es desa a «Projectes».|Diseño libre: un módulo con al menos un parámetro llamado 3 veces o más con valores distintos. Se guarda en «Proyectos».",
        diu: ["Quin paràmetre has triat? Per què aquest i no un altre?|¿Qué parámetro has elegido? ¿Por qué este y no otro?"], slides: ['s13'], app: "Pas «La família de peces».|Paso «La familia de piezas».", org: "Individual|Individual" },
      { min: 5, t: "Tancament|Cierre", fase: 'tancament', fa: "Repassa les idees clau i el tiquet de sortida.|Repasa las ideas clave y el ticket de salida.", diu: ["Què fa torre(50, 10)? On existeix el paràmetre alçada?|¿Qué hace torre(50, 10)? ¿Dónde existe el parámetro altura?"], slides: ['s14', 's15'], app: "Les últimes preguntes i «Com t'ha anat?».|Las últimas preguntas y «¿Cómo te ha ido?».", org: "Tot el grup|Todo el grupo" }
    ],
    errors: [["Intercanvia l'ordre dels valors a la crida.|Intercambia el orden de los valores en la llamada.", "Que llegeixi la línia de la definició i assigni en veu alta: «alçada = 40, gruix = 16». El primer valor sempre va al primer paràmetre.|Que lea la línea de la definición y asigne en voz alta: «altura = 40, grosor = 16». El primer valor siempre va al primer parámetro."],
      ["Fa servir el nom del paràmetre fora del mòdul i surt «la variable no existeix».|Usa el nombre del parámetro fuera del módulo y sale «la variable no existe».", "Els paràmetres només existeixen dins del seu mòdul. Fora, cal posar el número o una variable creada al programa.|Los parámetros solo existen dentro de su módulo. Fuera, hay que poner el número o una variable creada en el programa."],
      ["Afegeix el paràmetre a la definició però deixa el número fix a dins.|Añade el parámetro a la definición pero deja el número fijo dentro.", "Que busqui cada número que ha de canviar i el substitueixi pel nom del paràmetre (també al mou que puja el con).|Que busque cada número que tiene que cambiar y lo sustituya por el nombre del parámetro (también en el mueve que sube el cono)."]],
    diff: { mes: "Fer l'escala de cargol ⭐ i, després, un mòdul arbre(mida) on el gruix del tronc i la copa depenguin de la mida.|Hacer la escalera de caracol ⭐ y, después, un módulo árbol(tamaño) donde el grosor del tronco y la copa dependan del tamaño.",
      menys: "Començar amb mòduls d'un sol paràmetre (torre, pilar). Fer la taula de la fitxa (crida → valors → mides) abans de cada repte.|Empezar con módulos de un solo parámetro (torre, pilar). Hacer la tabla de la ficha (llamada → valores → medidas) antes de cada reto." },
    aval: { ticket: ["Amb defineix torre(alçada, gruix), què fa torre(50, 10)?|Con define torre(altura, grosor), ¿qué hace torre(50, 10)?", "Escriu un mòdul pilar(alçada) i crida'l amb 20 i amb 35.|Escribe un módulo pilar(altura) y llámalo con 20 y con 35."],
      rubric: [["Definir amb paràmetres|Definir con parámetros", "Fa servir els paràmetres a tots els llocs on calen.|Usa los parámetros en todos los sitios donde hacen falta.", "Deixa algun número fix que hauria de ser un paràmetre.|Deja algún número fijo que tendría que ser un parámetro."],
        ["Cridar|Llamar", "Posa els valors en l'ordre correcte i prediu el resultat.|Pone los valores en el orden correcto y predice el resultado.", "S'equivoca d'ordre i ho corregeix en veure el model.|Se equivoca de orden y lo corrige al ver el modelo."],
        ["Combinar|Combinar", "Fa servir paràmetres dins de càlculs i bucles, i crida mòduls des de bucles.|Usa parámetros dentro de cálculos y bucles, y llama a módulos desde bucles.", "Fa mòduls amb paràmetres simples, sense bucles.|Hace módulos con parámetros simples, sin bucles."]] },
    casa: "Pensa un objecte de casa que existeixi en moltes mides (gots, prestatgeries, tasses…). Escriu el seu mòdul amb paràmetres i tres crides per a tres mides diferents.|Piensa un objeto de casa que exista en muchos tamaños (vasos, estanterías, tazas…). Escribe su módulo con parámetros y tres llamadas para tres tamaños distintos.",
    intro: "Amb els paràmetres, els mòduls passen de ser segells fixos a ser receptes ajustables: és el cor del disseny paramètric. La idea d'ordre dels arguments i d'àmbit (els paràmetres només viuen dins del mòdul) mereix temps.|Con los parámetros, los módulos pasan de ser sellos fijos a ser recetas ajustables: es el corazón del diseño paramétrico. La idea de orden de los argumentos y de ámbito (los parámetros solo viven dentro del módulo) merece tiempo.",
    claus: ["Els paràmetres són buits de la recepta que s'omplen a cada crida.|Los parámetros son huecos de la receta que se rellenan en cada llamada.", "Els valors s'assignen per ordre.|Los valores se asignan por orden.", "Els paràmetres es poden fer servir en càlculs i en bucles dins del mòdul.|Los parámetros se pueden usar en cálculos y en bucles dentro del módulo.", "Un bucle que crida un mòdul amb el comptador fa una família de peces.|Un bucle que llama a un módulo con el contador hace una familia de piezas."],
    prev: ["Haver fet «Definir un mòdul».|Haber hecho «Definir un módulo».", "Saber fer servir variables i expressions (unitat 4).|Saber usar variables y expresiones (unidad 4).", "Saber fer bucles (unitat 5).|Saber hacer bucles (unidad 5)."],
    faq: [["Quants paràmetres pot tenir un mòdul?|¿Cuántos parámetros puede tener un módulo?", "Tants com calgui, però si en té molts costa recordar-ne l'ordre. Normalment, dos o tres; la resta es deixa fixa dins del mòdul.|Tantos como haga falta, pero si tiene muchos cuesta recordar su orden. Normalmente, dos o tres; el resto se deja fijo dentro del módulo."],
      ["Un paràmetre pot tenir el mateix nom que una variable del programa?|¿Un parámetro puede tener el mismo nombre que una variable del programa?", "Sí: dins del mòdul guanya el paràmetre. Però és millor fer servir noms diferents per no confondre's.|Sí: dentro del módulo gana el parámetro. Pero es mejor usar nombres distintos para no confundirse."],
      ["Puc passar un color com a paràmetre?|¿Puedo pasar un color como parámetro?", "En aquest taller, no: color() necessita el nom del color escrit. Els paràmetres són números (mides, posicions, quantitats).|En este taller, no: color() necesita el nombre del color escrito. Los parámetros son números (medidas, posiciones, cantidades)."]],
    tec: [["Surt «el mòdul … necessita 2 valors».|Sale «el módulo … necesita 2 valores».", "La crida porta menys (o més) valors que paràmetres té la definició. Compteu-los i afegiu el que falta.|La llamada lleva menos (o más) valores que parámetros tiene la definición. Contadlos y añadid el que falta."],
      ["Als blocs no surt el nom del paràmetre per triar-lo.|En los bloques no sale el nombre del parámetro para elegirlo.", "Els paràmetres surten com a opció només als camps de dins del mòdul. Comproveu que el bloc és dins de la definició.|Los parámetros salen como opción solo en los campos de dentro del módulo. Comprobad que el bloque está dentro de la definición."],
      ["Amb paraules amb accent (alçada) surt un error en escriure.|Con palabras con acento (altura) sale un error al escribir.", "Els noms amb ç o accents funcionen, però cal escriure'ls igual a tot arreu. Si costa, feu servir noms sense accent.|Los nombres con ç o acentos funcionan, pero hay que escribirlos igual en todas partes. Si cuesta, usad nombres sin acento."]],
    extra: ["Fer un mòdul prestatgeria(nivells, amplada) amb un bucle de prestatges.|Hacer un módulo estantería(niveles, ancho) con un bucle de estantes.", "Fer una escala de cargol paramètrica: esglaons(n, alçada_total).|Hacer una escalera de caracol paramétrica: peldaños(n, altura_total).", "Comparar el module d'OpenSCAD amb el nostre a l'exportació .scad.|Comparar el module de OpenSCAD con el nuestro en la exportación .scad."],
    trans: ["Sessió següent: la biblioteca de peces (organitzar i documentar el codi).|Sesión siguiente: la biblioteca de piezas (organizar y documentar el código).", "Matemàtiques: funcions i substitució de valors en expressions.|Matemáticas: funciones y sustitución de valores en expresiones."],
    slides: [
      { id: 's1', k: 'portada', t: 'Mòduls amb paràmetres|Módulos con parámetros', x: 'La mateixa recepta, amb les mides que diguis|La misma receta, con las medidas que digas', nota: "Presenta el problema: edificis i torres de totes les mides.|Presenta el problema: edificios y torres de todos los tamaños." },
      { id: 's2', k: 'pregunta', t: 'Un mòdul per a cada mida?|¿Un módulo para cada tamaño?', x: "Torres de 20, 30, 40, 50 i 60 mm. Cal fer 5 mòduls?|Torres de 20, 30, 40, 50 y 60 mm. ¿Hay que hacer 5 módulos?", nota: "Busquem la idea: un sol mòdul que rebi l'alçada.|Buscamos la idea: un solo módulo que reciba la altura." },
      { id: 's3', k: 'anim', t: 'Els buits de la recepta|Los huecos de la receta', anim: 'p6param', nota: "El valor de la crida omple el buit de la definició.|El valor de la llamada rellena el hueco de la definición." },
      { id: 's4', k: 'media', t: 'torre(alçada, gruix)|torre(altura, grosor)', media: { k: 'model', prog: B(TORRES) }, nota: "Llegiu cada crida i digueu quina alçada i quin gruix té.|Leed cada llamada y decid qué altura y qué grosor tiene." },
      { id: 's5', k: 'concepte', t: "L'ordre dels valors|El orden de los valores", punts: ["torre(40, 16): 40 d'alt, 16 de gruix.|torre(40, 16): 40 de alto, 16 de grosor.", "torre(16, 40): 16 d'alt, 40 de gruix.|torre(16, 40): 16 de alto, 40 de grosor."], code: CK(TORRE), nota: "El programa fa exactament el que li diem.|El programa hace exactamente lo que le decimos." },
      { id: 's6', k: 'media', t: 'Paràmetres, càlculs i bucles|Parámetros, cálculos y bucles', media: { k: 'model', prog: B(EDI) }, nota: "edifici(pisos): l'alçada i les files de finestres depenen de pisos.|edificio(pisos): la altura y las filas de ventanas dependen de pisos." },
      { id: 's7', k: 'media', t: 'Una família de torres|Una familia de torres', media: { k: 'model', prog: B(TFAM) }, nota: "El bucle crida el mòdul amb torre(20 + i * 10, 12).|El bucle llama al módulo con torre(20 + i * 10, 12)." },
      { id: 's8', k: 'activitat', t: 'Receptes amb buits|Recetas con huecos', timer: 8, punts: ["Llegiu casa(amplada, alçada).|Leed casa(ancho, altura).", "Dicteu i dibuixeu tres crides.|Dictad y dibujad tres llamadas.", "Proveu una crida amb els valors girats.|Probad una llamada con los valores girados."], nota: "Per parelles, amb la fitxa i paper quadriculat.|Por parejas, con la ficha y papel cuadriculado." },
      { id: 's9', k: 'pregunta', t: 'Prediu: quin bloc surt?|Predice: ¿qué bloque sale?', code: CK(`defineix bloc(costat, alçada) {\n  cub(costat, costat, alçada)\n}\nbloc(30, 10)`), nota: "costat = 30, alçada = 10: una placa quadrada.|lado = 30, altura = 10: una placa cuadrada." },
      { id: 's10', k: 'repte', t: "A l'ordinador|En el ordenador", punts: ["Troba els errors (bucle i ordre).|Encuentra los errores (bucle y orden).", "Paràmetres a la torre i a la tanca.|Parámetros en la torre y en la valla.", "Finestres de l'edifici i família de torres.|Ventanas del edificio y familia de torres."], nota: "Abans de canviar res, que diguin què val cada paràmetre.|Antes de cambiar nada, que digan qué vale cada parámetro." },
      { id: 's11', k: 'media', t: 'La tanca: dos paràmetres|La valla: dos parámetros', media: { k: 'model', prog: B(TANCA) }, nota: "La travessa fa (n − 1) × 12 + 4 i va a alçada − 8.|El travesaño mide (n − 1) × 12 + 4 y va en altura − 8." },
      { id: 's12', k: 'media', t: "L'escala de cargol ⭐|La escalera de caracol ⭐", media: { k: 'model', prog: B(SPIRAL) }, nota: "Cada esglaó puja 6 mm i gira 30° més: mòdul + bucle + gira.|Cada peldaño sube 6 mm y gira 30° más: módulo + bucle + gira." },
      { id: 's13', k: 'repte', t: 'La meva família de peces|Mi familia de piezas', punts: ["Un mòdul amb almenys un paràmetre.|Un módulo con al menos un parámetro.", "Tres crides amb valors diferents.|Tres llamadas con valores distintos.", "Tot a la placa.|Todo en la placa."], nota: "Idees: torres, arbres, ponts, fonts, piles de llibres.|Ideas: torres, árboles, puentes, fuentes, pilas de libros." },
      { id: 's14', k: 'resum', t: 'Avui hem après…|Hoy hemos aprendido…', punts: ["Els paràmetres són buits que s'omplen a cada crida.|Los parámetros son huecos que se rellenan en cada llamada.", "Els valors van per ordre.|Los valores van por orden.", "Mòdul + paràmetres + bucle = família de peces.|Módulo + parámetros + bucle = familia de piezas."], nota: "Llegiu-ho junts.|Leedlo juntos." },
      { id: 's15', k: 'tiquet', t: 'Tiquet de sortida|Ticket de salida', punts: ["Què fa torre(50, 10)?|¿Qué hace torre(50, 10)?", "Escriu pilar(alçada) i dues crides.|Escribe pilar(altura) y dos llamadas."], nota: "En un paper, abans de sortir.|En un papel, antes de salir." }
    ],
    print: [{ id: 'p1', t: 'Fitxa: receptes amb buits|Ficha: recetas con huecos', k: 'fitxa', intro: "El mòdul <code>casa(amplada, alçada)</code> fa un rectangle d'amplada × alçada caselles amb un triangle de teulada a sobre.|El módulo <code>casa(ancho, altura)</code> hace un rectángulo de ancho × altura casillas con un triángulo de tejado encima.",
      items: [{ q: "Dibuixa <code>casa(4, 3)</code>, <code>casa(2, 5)</code> i <code>casa(6, 2)</code>, una al costat de l'altra.|Dibuja <code>casa(4, 3)</code>, <code>casa(2, 5)</code> y <code>casa(6, 2)</code>, una al lado de la otra.", big: true, sol: "Tres cases: 4 × 3, 2 × 5 (alta i estreta) i 6 × 2 (ampla i baixa).|Tres casas: 4 × 3, 2 × 5 (alta y estrecha) y 6 × 2 (ancha y baja)." },
        { q: "Què canvia si en lloc de <code>casa(4, 3)</code> escrius <code>casa(3, 4)</code>?|¿Qué cambia si en lugar de <code>casa(4, 3)</code> escribes <code>casa(3, 4)</code>?", sol: "La casa passa a fer 3 d'ample i 4 d'alt: els valors s'assignen per ordre.|La casa pasa a medir 3 de ancho y 4 de alto: los valores se asignan por orden." },
        { q: "Amb <code>defineix torre(alçada, gruix)</code>, escriu la crida per fer una torre de 45 mm d'alt i 12 de gruix.|Con <code>define torre(altura, grosor)</code>, escribe la llamada para hacer una torre de 45 mm de alto y 12 de grosor.", sol: "torre(45, 12)|torre(45, 12)" },
        { q: "Inventa un mòdul amb un paràmetre per a la maqueta (nom, paràmetre i què fa) i escriu tres crides.|Inventa un módulo con un parámetro para la maqueta (nombre, parámetro y qué hace) y escribe tres llamadas.", big: true, sol: "Resposta oberta. Per exemple: arbre(mida) i arbre(10), arbre(15), arbre(20).|Respuesta abierta. Por ejemplo: árbol(tamaño) y árbol(10), árbol(15), árbol(20)." }] }]
  },
  /* ---------- Sessió 3 · La biblioteca de peces ---------- */
  'p6-3': {
    obj: ["L'alumne/a organitza un programa en tres parts (variables, biblioteca de mòduls i escena) i hi escriu comentaris útils.|El alumno/a organiza un programa en tres partes (variables, biblioteca de módulos y escena) y escribe comentarios útiles.",
      "L'alumne/a tria noms clars per a mòduls i paràmetres i respecta una convenció comuna (l'origen al centre de la base).|El alumno/a elige nombres claros para módulos y parámetros y respeta una convención común (el origen en el centro de la base).",
      "L'alumne/a fa servir mòduls escrits per altres llegint-ne el comentari i la definició, i en detecta els errors.|El alumno/a usa módulos escritos por otros leyendo su comentario y su definición, y detecta sus errores.",
      "L'alumne/a amplia una biblioteca amb un mòdul propi documentat i el fa servir en una escena.|El alumno/a amplía una biblioteca con un módulo propio documentado y lo usa en una escena."],
    comp: ["Competència digital: documentar i organitzar codi per treballar en equip|Competencia digital: documentar y organizar código para trabajar en equipo",
      "Pensament computacional: abstracció, interfícies (nom i paràmetres) i depuració de codi d'altres|Pensamiento computacional: abstracción, interfaces (nombre y parámetros) y depuración de código de otros",
      "Tecnologia i digitalització: convencions i normalització al disseny tècnic|Tecnología y digitalización: convenciones y normalización en el diseño técnico",
      "Comunicació lingüística: escriure descripcions tècniques breus i precises|Comunicación lingüística: escribir descripciones técnicas breves y precisas"],
    vocab: [["Biblioteca|Biblioteca", "Conjunt de mòduls preparats per fer-los servir en molts programes.|Conjunto de módulos preparados para usarlos en muchos programas."],
      ["Comentari|Comentario", "Text després de // que el taller no executa: explica el codi a les persones.|Texto después de // que el taller no ejecuta: explica el código a las personas."],
      ["Documentació|Documentación", "El que explica què fa un mòdul, els seus paràmetres i unitats, i un exemple.|Lo que explica qué hace un módulo, sus parámetros y unidades, y un ejemplo."],
      ["Convenció|Convención", "Una norma que tot l'equip segueix (per exemple, on és l'origen de cada mòdul).|Una norma que todo el equipo sigue (por ejemplo, dónde está el origen de cada módulo)."],
      ["Interfície d'un mòdul|Interfaz de un módulo", "El que cal saber per fer-lo servir: el nom i els paràmetres en ordre.|Lo que hay que saber para usarlo: el nombre y los parámetros en orden."]],
    mat: { aula: ["Un ordinador per alumne/a amb Numi Tech obert a la sessió «La biblioteca de peces»|Un ordenador por alumno/a con Numi Tech abierto en la sesión «La biblioteca de piezas»", "Projector i la presentació de la sessió|Proyector y la presentación de la sesión", "Fitxes de catàleg impreses (una per alumne/a) i llapis|Fichas de catálogo impresas (una por alumno/a) y lápiz"],
      imprimir: ["Fitxa: el catàleg de peces|Ficha: el catálogo de piezas"],
      prep: ["Imprimir les fitxes de catàleg.|Imprimir las fichas de catálogo.", "Fer els grups de 3 per al catàleg.|Hacer los grupos de 3 para el catálogo.", "Provar el repte de la font: el mòdul ha de tenir l'origen al centre de la base, com els altres.|Probar el reto de la fuente: el módulo tiene que tener el origen en el centro de la base, como los demás."] },
    plan: [
      { min: 5, t: "El codi de l'equip|El código del equipo", fase: 'inici', fa: "Ensenya un programa amb mòduls que es diuen m1, cosa i prova2, sense comentaris. Pregunta qui s'atreviria a fer-lo servir. Recorda què fa // i l'ordre dels paràmetres.|Enseña un programa con módulos que se llaman m1, cosa y prueba2, sin comentarios. Pregunta quién se atrevería a usarlo. Recuerda qué hace // y el orden de los parámetros.",
        diu: ["Què fa m1(20, 8)? Com ho podríem saber?|¿Qué hace m1(20, 8)? ¿Cómo podríamos saberlo?"], slides: ['s1', 's2'], app: "Encara no: pantalles abaixades.|Todavía no: pantallas bajadas.", org: "Tot el grup|Todo el grupo" },
      { min: 12, t: "Organitzar i documentar|Organizar y documentar", fase: 'teoria', fa: "Presenta les tres parts d'un programa, els comentaris, els noms clars i la convenció de l'origen al centre de la base (amb el banc). Llegiu junts la biblioteca de la maqueta i la plaça: prediu cada crida abans de mirar el model.|Presenta las tres partes de un programa, los comentarios, los nombres claros y la convención del origen en el centro de la base (con el banco). Leed juntos la biblioteca de la maqueta y la plaza: predice cada llamada antes de mirar el modelo.",
        diu: ["Per què el banc comença a −llargada / 2?|¿Por qué el banco empieza en −largo / 2?", "Què ha de dir el comentari d'un mòdul?|¿Qué tiene que decir el comentario de un módulo?"], slides: ['s3', 's4', 's5', 's6', 's7'], app: "Encara no: tota l'atenció a la projecció.|Todavía no: toda la atención en la proyección.", org: "Tot el grup|Todo el grupo" },
      { min: 10, t: "El catàleg de peces|El catálogo de piezas", fase: 'desconnectat', fa: "En grups de 3: cadascú omple una fitxa de catàleg d'un element de la maqueta. Es passen les fitxes i cadascú escriu una crida sense preguntar res. Després comproven si la crida fa el que volia l'autor i què faltava a la fitxa.|En grupos de 3: cada uno rellena una ficha de catálogo de un elemento de la maqueta. Se pasan las fichas y cada uno escribe una llamada sin preguntar nada. Después comprueban si la llamada hace lo que quería el autor y qué faltaba en la ficha.",
        diu: ["Has pogut fer la crida només amb la fitxa? Què hi faltava?|¿Has podido hacer la llamada solo con la ficha? ¿Qué faltaba?"], slides: ['s8'], app: "Encara no: fitxes de catàleg.|Todavía no: fichas de catálogo.", org: "Grups de 3|Grupos de 3" },
      { min: 22, t: "A l'ordinador: la plaça|En el ordenador: la plaza", fase: 'ordinador', fa: "Fan l'app: predicció amb el mòdul d'un company, dos errors (la convenció del banc i una crida girada) i els reptes: muntar la plaça amb la biblioteca, arreglar l'arbre que no s'adapta, afegir la font i el mòdul filera. Al repte de l'arbre, fes-los notar que un número fix dins d'un mòdul amb paràmetres és sospitós.|Hacen la app: predicción con el módulo de un compañero, dos errores (la convención del banco y una llamada girada) y los retos: montar la plaza con la biblioteca, arreglar el árbol que no se adapta, añadir la fuente y el módulo hilera. En el reto del árbol, hazles notar que un número fijo dentro de un módulo con parámetros es sospechoso.",
        diu: ["Què diu el comentari del mòdul? En quin ordre van els valors?|¿Qué dice el comentario del módulo? ¿En qué orden van los valores?", "La teva font segueix la convenció de l'origen?|¿Tu fuente sigue la convención del origen?"], slides: ['s9', 's10', 's11', 's12'], app: "Sessió «La biblioteca de peces», fins al disseny lliure.|Sesión «La biblioteca de piezas», hasta el diseño libre.", org: "Individual|Individual" },
      { min: 6, t: "Amplia la biblioteca|Amplía la biblioteca", fase: 'crea', fa: "Cada alumne/a afegeix a la biblioteca un mòdul propi documentat (comentari, nom clar, origen al centre) i el fa servir dues vegades en una escena. Es desa a «Projectes».|Cada alumno/a añade a la biblioteca un módulo propio documentado (comentario, nombre claro, origen en el centro) y lo usa dos veces en una escena. Se guarda en «Proyectos».",
        diu: ["Un company podria fer servir el teu mòdul només llegint el comentari?|¿Un compañero podría usar tu módulo solo leyendo el comentario?"], slides: ['s13'], app: "Pas «Amplia la biblioteca».|Paso «Amplía la biblioteca».", org: "Individual|Individual" },
      { min: 5, t: "Tancament|Cierre", fase: 'tancament', fa: "Repassa les idees clau i el tiquet de sortida.|Repasa las ideas clave y el ticket de salida.", diu: ["Quines tres parts té un programa ben organitzat?|¿Qué tres partes tiene un programa bien organizado?"], slides: ['s14', 's15'], app: "Les últimes preguntes i «Com t'ha anat?».|Las últimas preguntas y «¿Cómo te ha ido?».", org: "Tot el grup|Todo el grupo" }
    ],
    errors: [["Escriu comentaris que no diuen res útil (// el meu mòdul).|Escribe comentarios que no dicen nada útil (// mi módulo).", "Un bon comentari respon: què fa?, què vol dir cada paràmetre (i en quines unitats)?, on és l'origen? Que el comparin amb els de la biblioteca.|Un buen comentario responde: ¿qué hace?, ¿qué quiere decir cada parámetro (y en qué unidades)?, ¿dónde está el origen? Que lo comparen con los de la biblioteca."],
      ["El seu mòdul té l'origen a la cantonada i queda desplaçat a l'escena.|Su módulo tiene el origen en la esquina y queda desplazado en la escena.", "Que segueixi la convenció: centrar en x i y restant la meitat de l'amplada i la fondària (o fent servir «centrat»), amb la base a z = 0.|Que siga la convención: centrar en x e y restando la mitad de la anchura y el fondo (o usando «centrado»), con la base en z = 0."],
      ["Posa el comentari al final d'una línia de codi (z = 12 // dents) i surt un error estrany.|Pone el comentario al final de una línea de código (z = 12 // dientes) y sale un error extraño.", "En aquest taller, els comentaris han d'anar en una línia a part, a sobre del codi que expliquen.|En este taller, los comentarios tienen que ir en una línea aparte, encima del código que explican."]],
    diff: { mes: "Fer la plaça paramètrica ⭐ (n bancs en cercle) i, després, documentar-la amb un comentari que expliqui la variable n.|Hacer la plaza paramétrica ⭐ (n bancos en círculo) y, después, documentarla con un comentario que explique la variable n.",
      menys: "Treballar la biblioteca amb un sol mòdul cada vegada, tapant els altres. Fer la fitxa de catàleg en parella.|Trabajar la biblioteca con un solo módulo cada vez, tapando los demás. Hacer la ficha de catálogo en pareja." },
    aval: { ticket: ["Quines tres parts té un programa ben organitzat?|¿Qué tres partes tiene un programa bien organizado?", "Escriu el comentari per a un mòdul paperera(alçada).|Escribe el comentario para un módulo papelera(altura)."],
      rubric: [["Documentar|Documentar", "Els comentaris expliquen què fa el mòdul, els paràmetres i les unitats.|Los comentarios explican qué hace el módulo, los parámetros y las unidades.", "Hi ha comentaris, però incomplets o poc clars.|Hay comentarios, pero incompletos o poco claros."],
        ["Organitzar|Organizar", "El programa té les tres parts i segueix la convenció de l'origen.|El programa tiene las tres partes y sigue la convención del origen.", "El programa funciona però està barrejat.|El programa funciona pero está mezclado."],
        ["Fer servir codi d'altres|Usar código de otros", "Fa servir els mòduls llegint la documentació i en troba els errors.|Usa los módulos leyendo la documentación y encuentra sus errores.", "Necessita provar diverses vegades per entendre els mòduls.|Necesita probar varias veces para entender los módulos."]] },
    casa: "Fes la fitxa de catàleg d'un objecte de casa com si fos un mòdul: nom, què fa, paràmetres amb unitats, una crida d'exemple i un esbós amb l'origen marcat.|Haz la ficha de catálogo de un objeto de casa como si fuera un módulo: nombre, qué hace, parámetros con unidades, una llamada de ejemplo y un boceto con el origen marcado.",
    intro: "Sessió de bones pràctiques i de lectura de codi: quan el programa creix i el comparteixen diverses persones, l'organització i la documentació són tan importants com que funcioni. És un bon moment per treballar en equip.|Sesión de buenas prácticas y de lectura de código: cuando el programa crece y lo comparten varias personas, la organización y la documentación son tan importantes como que funcione. Es un buen momento para trabajar en equipo.",
    claus: ["Un programa ben organitzat: variables, biblioteca de mòduls i escena.|Un programa bien organizado: variables, biblioteca de módulos y escena.", "Cada mòdul porta un comentari: què fa, paràmetres i unitats.|Cada módulo lleva un comentario: qué hace, parámetros y unidades.", "Noms clars i una convenció comuna per a l'origen.|Nombres claros y una convención común para el origen.", "Per fer servir codi d'altres: llegir, predir, provar i modificar.|Para usar código de otros: leer, predecir, probar y modificar."],
    prev: ["Haver fet «Definir un mòdul» i «Mòduls amb paràmetres».|Haber hecho «Definir un módulo» y «Módulos con parámetros».", "Saber fer servir mou i gira.|Saber usar mueve y gira.", "Conèixer els comentaris //.|Conocer los comentarios //."],
    faq: [["Per què posar comentaris si el programa ja funciona?|¿Por qué poner comentarios si el programa ya funciona?", "Perquè d'aquí a un mes (o un company) l'haurà d'entendre i canviar. El codi s'escriu una vegada i es llegeix moltes.|Porque dentro de un mes (o un compañero) tendrá que entenderlo y cambiarlo. El código se escribe una vez y se lee muchas."],
      ["Hi ha biblioteques de peces de veritat?|¿Hay bibliotecas de piezas de verdad?", "Sí: OpenSCAD en té moltes (cargols, engranatges, caixes…), i els enginyers en fan servir de comercials. Sempre amb documentació.|Sí: OpenSCAD tiene muchas (tornillos, engranajes, cajas…), y los ingenieros usan comerciales. Siempre con documentación."],
      ["Per què l'origen al centre de la base i no a la cantonada?|¿Por qué el origen en el centro de la base y no en la esquina?", "Qualsevol convenció funciona si tothom la segueix. El centre de la base és pràctic per girar peces i per posar-les a sobre de la placa.|Cualquier convención funciona si todo el mundo la sigue. El centro de la base es práctico para girar piezas y para ponerlas encima de la placa."]],
    tec: [["Un comentari al final d'una línia fa saltar un error.|Un comentario al final de una línea hace saltar un error.", "Poseu els comentaris en una línia a part, a sobre del codi.|Poned los comentarios en una línea aparte, encima del código."],
      ["Al mode blocs els comentaris surten com a blocs grisos.|En el modo bloques los comentarios salen como bloques grises.", "És normal: el bloc «// nota» és un comentari. Es pot editar tocant-lo.|Es normal: el bloque «// nota» es un comentario. Se puede editar tocándolo."],
      ["La biblioteca és llarga i no es veu l'escena.|La biblioteca es larga y no se ve la escena.", "A la pestanya «Codi», desplaceu-vos fins al final: l'escena va a sota de la biblioteca.|En la pestaña «Código», desplazaos hasta el final: la escena va debajo de la biblioteca."]],
    extra: ["Fer la fitxa de catàleg digital: una diapositiva per mòdul amb una captura i la crida d'exemple.|Hacer la ficha de catálogo digital: una diapositiva por módulo con una captura y la llamada de ejemplo.", "Revisar el codi d'un company amb la rúbrica (noms, comentaris, convenció) i proposar millores.|Revisar el código de un compañero con la rúbrica (nombres, comentarios, convención) y proponer mejoras.", "Mirar una biblioteca d'OpenSCAD real i identificar-ne els comentaris i els paràmetres.|Mirar una biblioteca de OpenSCAD real e identificar sus comentarios y parámetros."],
    trans: ["Sessió següent: projecte de la ciutat modular.|Sesión siguiente: proyecto de la ciudad modular.", "Llengua: textos instructius i descriptius breus i precisos.|Lengua: textos instructivos y descriptivos breves y precisos."],
    slides: [
      { id: 's1', k: 'portada', t: 'La biblioteca de peces|La biblioteca de piezas', x: "Codi que tothom pot entendre i fer servir|Código que todo el mundo puede entender y usar", nota: "Tres enginyers, molts mòduls: cal posar ordre.|Tres ingenieros, muchos módulos: hay que poner orden." },
      { id: 's2', k: 'pregunta', t: 'Què fa m1(20, 8)?|¿Qué hace m1(20, 8)?', x: "Sense comentaris ni noms clars, com ho podem saber?|Sin comentarios ni nombres claros, ¿cómo podemos saberlo?", code: CK(`defineix m1(a, b) {\n  cub(4, 6, b)\n  mou(a - 4, 0, 0) cub(4, 6, b)\n  mou(0, 0, b) cub(a, 6, 4)\n}\nm1(20, 8)`), nota: "És la porta! Però només ho sabem si llegim tot el codi.|¡Es la puerta! Pero solo lo sabemos si leemos todo el código." },
      { id: 's3', k: 'anim', t: 'Les tres parts d\'un programa|Las tres partes de un programa', anim: 'p6lib', nota: "Paràmetres, mòduls i escena; les fletxes van de les crides a les definicions.|Parámetros, módulos y escena; las flechas van de las llamadas a las definiciones." },
      { id: 's4', k: 'media', t: 'Comentaris i noms clars|Comentarios y nombres claros', media: { k: 'model', prog: B(`${PORTA}\nporta(30, 20)`) }, nota: "El mateix mòdul que m1, però ara s'entén sense obrir-lo.|El mismo módulo que m1, pero ahora se entiende sin abrirlo." },
      { id: 's5', k: 'media', t: "La convenció: origen al centre|La convención: origen en el centro", media: { k: 'model', prog: B(`${LBANC}\nbanc(36)\nmou(0, 25, 0) banc(20)`) }, nota: "El banc comença a −llargada / 2: queda centrat a l'origen.|El banco empieza en −largo / 2: queda centrado en el origen." },
      { id: 's6', k: 'media', t: 'La biblioteca i la plaça|La biblioteca y la plaza', media: { k: 'model', prog: B(PLACA) }, nota: "Llegiu el comentari de cada mòdul abans de mirar la crida.|Leed el comentario de cada módulo antes de mirar la llamada." },
      { id: 's7', k: 'concepte', t: 'Fer servir codi d\'altres|Usar código de otros', punts: ["Llegeix el comentari i els paràmetres.|Lee el comentario y los parámetros.", "Prediu què farà la crida.|Predice qué hará la llamada.", "Prova-ho i, si cal, modifica.|Pruébalo y, si hace falta, modifica."], nota: "El mètode de sempre: predir, executar, investigar, modificar.|El método de siempre: predecir, ejecutar, investigar, modificar." },
      { id: 's8', k: 'activitat', t: 'El catàleg de peces|El catálogo de piezas', timer: 9, punts: ["Omple la fitxa del teu mòdul.|Rellena la ficha de tu módulo.", "Passa-la: el company escriu una crida sense preguntar.|Pásala: el compañero escribe una llamada sin preguntar.", "Comproveu-ho: què faltava?|Comprobadlo: ¿qué faltaba?"], nota: "Grups de 3, amb les fitxes de catàleg.|Grupos de 3, con las fichas de catálogo." },
      { id: 's9', k: 'pregunta', t: "L'arbre que no s'adapta|El árbol que no se adapta", x: "Per què l'arbre petit té la copa flotant i el gran, enfonsada?|¿Por qué el árbol pequeño tiene la copa flotando y el grande, hundida?", code: CK(`defineix arbre(mida) {\n  cilindre(mida / 4, mida)\n  mou(0, 0, 16) esfera(mida)\n}`), nota: "El 16 és fix: la copa només està bé quan mida = 16.|El 16 es fijo: la copa solo está bien cuando tamaño = 16." },
      { id: 's10', k: 'repte', t: "A l'ordinador|En el ordenador", punts: ["La plaça amb la biblioteca.|La plaza con la biblioteca.", "Arregla l'arbre i afegeix la font.|Arregla el árbol y añade la fuente.", "El mòdul filera(n).|El módulo hilera(n)."], nota: "Que llegeixin els comentaris abans de tocar el codi.|Que lean los comentarios antes de tocar el código." },
      { id: 's11', k: 'media', t: 'Arbres que sí que s\'adapten|Árboles que sí se adaptan', media: { k: 'model', prog: B(ARBRES3) }, nota: "Amb mou(0, 0, mida), la copa és sempre a dalt del tronc.|Con mueve(0, 0, tamaño), la copa está siempre encima del tronco." },
      { id: 's12', k: 'concepte', t: 'Un mòdul nou: la font|Un módulo nuevo: la fuente', punts: ["Comentari a sobre.|Comentario encima.", "Origen al centre de la base.|Origen en el centro de la base.", "Un paràmetre: d (diàmetre).|Un parámetro: d (diámetro)."], code: CK(`// font(d): bassa i sortidor; d = diàmetre\ndefineix font(d) {\n  cilindre(d, 2)\n  tub(d, 8, 2)\n  cilindre(4, 14)\n  mou(0, 0, 14) esfera(8)\n}`), nota: "Segueix la mateixa convenció que la resta de la biblioteca.|Sigue la misma convención que el resto de la biblioteca." },
      { id: 's13', k: 'repte', t: 'Amplia la biblioteca|Amplía la biblioteca', punts: ["Un mòdul teu amb comentari.|Un módulo tuyo con comentario.", "Nom clar i origen al centre.|Nombre claro y origen en el centro.", "Fes-lo servir dues vegades.|Úsalo dos veces."], nota: "Idees: paperera, gronxador, parada de bus, escultura.|Ideas: papelera, columpio, parada de bus, escultura." },
      { id: 's14', k: 'resum', t: 'Avui hem après…|Hoy hemos aprendido…', punts: ["Variables, mòduls i escena.|Variables, módulos y escena.", "Comentaris, noms clars i convencions.|Comentarios, nombres claros y convenciones.", "Llegir codi d'altres abans de fer-lo servir.|Leer código de otros antes de usarlo."], nota: "Llegiu-ho junts.|Leedlo juntos." },
      { id: 's15', k: 'tiquet', t: 'Tiquet de sortida|Ticket de salida', punts: ["Les tres parts d'un programa.|Las tres partes de un programa.", "El comentari de paperera(alçada).|El comentario de papelera(altura)."], nota: "En un paper, abans de sortir.|En un papel, antes de salir." }
    ],
    print: [{ id: 'p1', t: 'Fitxa: el catàleg de peces|Ficha: el catálogo de piezas', k: 'fitxa', intro: "Omple la fitxa de catàleg del teu mòdul. Una altra persona l'haurà de fer servir sense preguntar-te res!|Rellena la ficha de catálogo de tu módulo. ¡Otra persona tendrá que usarlo sin preguntarte nada!",
      items: [{ q: "Nom del mòdul i què fa (una frase).|Nombre del módulo y qué hace (una frase).", sol: "Resposta oberta. Ex.: paperera(alçada): un cilindre buit amb una tapa; l'origen al centre de la base.|Respuesta abierta. Ej.: papelera(altura): un cilindro hueco con una tapa; el origen en el centro de la base." },
        { q: "Paràmetres, en ordre, amb el que vol dir cada un i les unitats.|Parámetros, en orden, con lo que quiere decir cada uno y las unidades.", sol: "Ex.: 1) alçada: mm, de 10 a 40.|Ej.: 1) altura: mm, de 10 a 40." },
        { q: "Una crida d'exemple i un esbós de la vista de dalt amb l'origen marcat (×).|Una llamada de ejemplo y un boceto de la vista de arriba con el origen marcado (×).", big: true, sol: "Ex.: paperera(25). L'origen ha de ser al centre de la base.|Ej.: papelera(25). El origen tiene que estar en el centro de la base." },
        { q: "Ho ha entès el company? Escriu aquí la seva crida i què faltava a la fitxa.|¿Lo ha entendido el compañero? Escribe aquí su llamada y qué faltaba en la ficha.", sol: "Resposta oberta: sovint falten les unitats o on és l'origen.|Respuesta abierta: a menudo faltan las unidades o dónde está el origen." }] }]
  },
  /* ---------- Sessió 4 · Projecte: la ciutat modular ---------- */
  'p6-4': {
    obj: ["L'alumne/a planifica un model gran: esbós a escala, llista de mòduls amb paràmetres i què es repeteix.|El alumno/a planifica un modelo grande: boceto a escala, lista de módulos con parámetros y qué se repite.",
      "L'alumne/a construeix i prova cada mòdul per separat abans de muntar l'escena.|El alumno/a construye y prueba cada módulo por separado antes de montar la escena.",
      "L'alumne/a combina mòduls, bucles niats i paràmetres per generar una illa de ciutat amb poques línies.|El alumno/a combina módulos, bucles anidados y parámetros para generar una manzana de ciudad con pocas líneas.",
      "L'alumne/a comprova que el model es pot fabricar (una peça, cap dins de la placa, res que floti) i el presenta.|El alumno/a comprueba que el modelo se puede fabricar (una pieza, cabe en la placa, nada que flote) y lo presenta."],
    comp: ["Tecnologia i digitalització: procés tecnològic complet (planificar, dissenyar, construir, provar, fabricar)|Tecnología y digitalización: proceso tecnológico completo (planificar, diseñar, construir, probar, fabricar)",
      "Pensament computacional: descomposició, abstracció (mòduls) i generalització (paràmetres)|Pensamiento computacional: descomposición, abstracción (módulos) y generalización (parámetros)",
      "Matemàtiques: escala, coordenades i expressions amb dues variables|Matemáticas: escala, coordenadas y expresiones con dos variables",
      "Competència personal i social: planificar un projecte i comunicar-ne les decisions|Competencia personal y social: planificar un proyecto y comunicar sus decisiones"],
    vocab: [["Projecte|Proyecto", "Un treball gran que es planifica i es fa per passos fins a un producte.|Un trabajo grande que se planifica y se hace por pasos hasta un producto."],
      ["Esbós a escala|Boceto a escala", "Dibuix on cada casella representa una mida real (aquí, 10 mm).|Dibujo donde cada casilla representa una medida real (aquí, 10 mm)."],
      ["Escena|Escena", "La part del programa que col·loca i combina els mòduls.|La parte del programa que coloca y combina los módulos."],
      ["Illa de cases|Manzana", "Un bloc de la ciutat envoltat de carrers.|Un bloque de la ciudad rodeado de calles."],
      ["Prova unitària|Prueba unitaria", "Provar cada mòdul tot sol abans de fer-lo servir en el conjunt.|Probar cada módulo solo antes de usarlo en el conjunto."]],
    mat: { aula: ["Un ordinador per alumne/a amb Numi Tech obert a la sessió «Projecte: la ciutat modular»|Un ordenador por alumno/a con Numi Tech abierto en la sesión «Proyecto: la ciudad modular»", "Projector i la presentació de la sessió|Proyector y la presentación de la sesión", "Fitxa del projecte amb el quadrat de 12 × 12 caselles, llapis i colors|Ficha del proyecto con el cuadrado de 12 × 12 casillas, lápiz y colores"],
      imprimir: ["Fitxa del projecte: l'esbós de la illa|Ficha del proyecto: el boceto de la manzana"],
      prep: ["Imprimir les fitxes del projecte.|Imprimir las fichas del proyecto.", "Provar el pas 4 (barri paramètric) amb n = 2 i n = 4.|Probar el paso 4 (barrio paramétrico) con n = 2 y n = 4.", "Si teniu impressora 3D, decidir quines illes s'imprimiran i l'ordre (cada illa de 120 mm triga força).|Si tenéis impresora 3D, decidir qué manzanas se imprimirán y el orden (cada manzana de 120 mm tarda bastante)."] },
    plan: [
      { min: 5, t: "El barri del futur|El barrio del futuro", fase: 'inici', fa: "Presenta l'encàrrec: cada alumne/a fa una illa de 120 × 120 mm i després les ajuntarem. Recorda els mòduls amb bucles amb la predicció del carrer.|Presenta el encargo: cada alumno/a hace una manzana de 120 × 120 mm y después las juntaremos. Recuerda los módulos con bucles con la predicción de la calle.",
        diu: ["Quines peces es repetiran a la vostra illa?|¿Qué piezas se repetirán en vuestra manzana?"], slides: ['s1', 's2'], app: "Encara no: pantalles abaixades.|Todavía no: pantallas bajadas.", org: "Tot el grup|Todo el grupo" },
      { min: 8, t: "Com es fa un projecte gran|Cómo se hace un proyecto grande", fase: 'teoria', fa: "Presenta el pla (esbós, mòduls, prova, escena, imprimir) i l'exemple: el mòdul edifici, la illa amb dos bucles niats i la versió amb la variable n. Insisteix en les tres parts del programa i en les comprovacions de fabricació.|Presenta el plan (boceto, módulos, prueba, escena, imprimir) y el ejemplo: el módulo edificio, la manzana con dos bucles anidados y la versión con la variable n. Insiste en las tres partes del programa y en las comprobaciones de fabricación.",
        diu: ["Per què es prova cada mòdul sol abans de fer la illa?|¿Por qué se prueba cada módulo solo antes de hacer la manzana?"], slides: ['s3', 's4', 's5', 's6', 's7'], app: "Encara no: tota l'atenció a la projecció.|Todavía no: toda la atención en la proyección.", org: "Tot el grup|Todo el grupo" },
      { min: 8, t: "L'esbós de la illa|El boceto de la manzana", fase: 'desconnectat', fa: "Individualment, amb la fitxa: dibuixen la vista de dalt a escala (1 casella = 10 mm), fan la llista de mòduls amb paràmetres i marquen què es repeteix.|Individualmente, con la ficha: dibujan la vista de arriba a escala (1 casilla = 10 mm), hacen la lista de módulos con parámetros y marcan qué se repite.",
        diu: ["Quina variable faria canviar tot el barri?|¿Qué variable haría cambiar todo el barrio?"], slides: ['s8'], app: "Encara no: fitxa del projecte.|Todavía no: ficha del proyecto.", org: "Individual|Individual" },
      { min: 20, t: "A l'ordinador: de l'edifici a la illa|En el ordenador: del edificio a la manzana", fase: 'ordinador', fa: "Fan l'app: predicció, dos errors (edificis que es trepitgen i terrats que floten) i els quatre passos guiats (mòdul, carrer, illa i barri paramètric). Són el model de com construir el seu projecte.|Hacen la app: predicción, dos errores (edificios que se pisan y azoteas que flotan) y los cuatro pasos guiados (módulo, calle, manzana y barrio paramétrico). Son el modelo de cómo construir su proyecto.",
        diu: ["Quina distància hi ha entre edificis? Hi cap un carrer?|¿Qué distancia hay entre edificios? ¿Cabe una calle?", "Amb n = 4, encara cap a la placa?|Con n = 4, ¿todavía cabe en la placa?"], slides: ['s9', 's10', 's11', 's12'], app: "Sessió «Projecte: la ciutat modular», fins al projecte.|Sesión «Proyecto: la ciudad modular», hasta el proyecto.", org: "Individual|Individual" },
      { min: 14, t: "La meva illa|Mi manzana", fase: 'crea', fa: "Projecte: cada alumne/a programa la seva illa seguint l'esbós: mòduls propis (un amb paràmetres), bucles, una sola peça dins de 120 × 120 mm. Es desa a «Projectes» amb l'STL. Si hi ha temps, ajunteu les captures de totes les illes a la pissarra digital.|Proyecto: cada alumno/a programa su manzana siguiendo el boceto: módulos propios (uno con parámetros), bucles, una sola pieza dentro de 120 × 120 mm. Se guarda en «Proyectos» con el STL. Si hay tiempo, juntad las capturas de todas las manzanas en la pizarra digital.",
        diu: ["Has provat cada mòdul sol? Quina comprovació et falta?|¿Has probado cada módulo solo? ¿Qué comprobación te falta?"], slides: ['s13'], app: "Pas «Projecte: la teva illa de la ciutat modular».|Paso «Proyecto: tu manzana de la ciudad modular».", org: "Individual|Individual" },
      { min: 5, t: "Exposició i tancament|Exposición y cierre", fase: 'tancament', fa: "Dos o tres alumnes presenten la seva illa: mòduls, paràmetres i què canvia la variable principal. Tiquet de sortida.|Dos o tres alumnos presentan su manzana: módulos, parámetros y qué cambia la variable principal. Ticket de salida.", diu: ["Quin mòdul has fet servir més vegades? Amb quantes línies?|¿Qué módulo has usado más veces? ¿Con cuántas líneas?"], slides: ['s14', 's15'], app: "Les últimes preguntes i «Com t'ha anat?».|Las últimas preguntas y «¿Cómo te ha ido?».", org: "Tot el grup|Todo el grupo" }
    ],
    errors: [["Comença a programar sense esbós i la illa no hi cap.|Empieza a programar sin boceto y la manzana no cabe.", "Que torni a l'esbós: amb la quadrícula de 10 mm és fàcil veure quants edificis caben i amb quin pas.|Que vuelva al boceto: con la cuadrícula de 10 mm es fácil ver cuántos edificios caben y con qué paso."],
      ["Els edificis o els arbres floten o queden enterrats a la base.|Los edificios o los árboles flotan o quedan enterrados en la base.", "La base fa 3 mm: tot el que hi va a sobre ha de començar a z = 3. La comprovació «una sola peça» ajuda a trobar-ho.|La base mide 3 mm: todo lo que va encima tiene que empezar en z = 3. La comprobación «una sola pieza» ayuda a encontrarlo."],
      ["Programa tota la illa de cop i, quan falla, no sap on és l'error.|Programa toda la manzana de golpe y, cuando falla, no sabe dónde está el error.", "Que provi cada mòdul sol amb una o dues crides i que munti l'escena a poc a poc, comprovant després de cada bucle.|Que pruebe cada módulo solo con una o dos llamadas y que monte la escena poco a poco, comprobando después de cada bucle."]],
    diff: { mes: "Afegir un segon paràmetre global (per exemple, l'alçada màxima) i un mòdul de parc amb arbres en cercle. Fer la versió paramètrica de la seva illa.|Añadir un segundo parámetro global (por ejemplo, la altura máxima) y un módulo de parque con árboles en círculo. Hacer la versión paramétrica de su manzana.",
      menys: "Partir de la illa del pas 3 i personalitzar-la: canviar el mòdul edifici (teulada, colors) i afegir un mòdul arbre en els espais buits.|Partir de la manzana del paso 3 y personalizarla: cambiar el módulo edificio (tejado, colores) y añadir un módulo árbol en los espacios vacíos." },
    aval: { ticket: ["Quins passos té el pla d'un projecte gran?|¿Qué pasos tiene el plan de un proyecto grande?", "Amb n = 4 a la illa paramètrica, quants edificis hi ha?|Con n = 4 en la manzana paramétrica, ¿cuántos edificios hay?"],
      rubric: [["Planificació|Planificación", "L'esbós, la llista de mòduls i el programa coincideixen.|El boceto, la lista de módulos y el programa coinciden.", "Hi ha esbós, però el programa se n'allunya molt.|Hay boceto, pero el programa se aleja mucho de él."],
        ["Mòduls i bucles|Módulos y bucles", "Almenys dos mòduls (un amb paràmetres) i bucles per a tot el que es repeteix.|Al menos dos módulos (uno con parámetros) y bucles para todo lo que se repite.", "Un sol mòdul o còpies de codi en lloc de bucles.|Un solo módulo o copias de código en lugar de bucles."],
        ["Fabricació i presentació|Fabricación y presentación", "Una sola peça dins de 120 × 120 mm; explica el disseny amb vocabulari tècnic.|Una sola pieza dentro de 120 × 120 mm; explica el diseño con vocabulario técnico.", "Hi ha peces soltes o fora de mida; l'explicació és poc precisa.|Hay piezas sueltas o fuera de medida; la explicación es poco precisa."]] },
    casa: "Fes una foto (o un dibuix) d'una illa de cases del teu barri des de dalt (amb un mapa). Quants edificis té? Quins elements es repeteixen? Quins mòduls faries servir?|Haz una foto (o un dibujo) de una manzana de tu barrio desde arriba (con un mapa). ¿Cuántos edificios tiene? ¿Qué elementos se repiten? ¿Qué módulos usarías?",
    intro: "Projecte de la unitat: tot el que saben del curs fins ara (formes, transformacions, booleanes, variables, bucles i mòduls) en un model gran i fabricable. Els quatre passos guiats de l'app són la plantilla del seu propi projecte.|Proyecto de la unidad: todo lo que saben del curso hasta ahora (formas, transformaciones, booleanas, variables, bucles y módulos) en un modelo grande y fabricable. Los cuatro pasos guiados de la app son la plantilla de su propio proyecto.",
    claus: ["Un projecte gran: esbós, mòduls, prova, escena, fabricació.|Un proyecto grande: boceto, módulos, prueba, escena, fabricación.", "Cada mòdul es prova sol abans de fer-lo servir.|Cada módulo se prueba solo antes de usarlo.", "Bucles niats + mòdul paramètric = una illa sencera amb poques línies.|Bucles anidados + módulo paramétrico = una manzana entera con pocas líneas.", "Una variable al principi pot canviar tot el barri.|Una variable al principio puede cambiar todo el barrio."],
    prev: ["Haver fet les tres sessions anteriors de mòduls.|Haber hecho las tres sesiones anteriores de módulos.", "Saber fer bucles niats (unitat 5).|Saber hacer bucles anidados (unidad 5).", "Saber dibuixar a escala amb quadrícula.|Saber dibujar a escala con cuadrícula."],
    faq: [["Puc fer una illa que no sigui quadrada?|¿Puedo hacer una manzana que no sea cuadrada?", "Sí, mentre càpiga dins de 120 × 120 mm i sigui una sola peça. Si voleu que encaixi amb les dels companys, millor respectar la vora.|Sí, mientras quepa dentro de 120 × 120 mm y sea una sola pieza. Si queréis que encaje con las de los compañeros, mejor respetar el borde."],
      ["Quant triga a imprimir-se una illa?|¿Cuánto tarda en imprimirse una manzana?", "Depèn de la impressora i de l'alçada dels edificis: poden ser unes hores. Per això convé que la base sigui fina i els edificis no massa alts.|Depende de la impresora y de la altura de los edificios: pueden ser unas horas. Por eso conviene que la base sea fina y los edificios no demasiado altos."],
      ["Puc fer servir els mòduls de la biblioteca de la sessió anterior?|¿Puedo usar los módulos de la biblioteca de la sesión anterior?", "És clar: copieu-los al vostre programa (amb els comentaris). Reutilitzar és precisament el que volem!|Claro: copiadlos en vuestro programa (con los comentarios). ¡Reutilizar es precisamente lo que queremos!"]],
    tec: [["El 3D va molt lent amb la illa sencera.|El 3D va muy lento con la manzana entera.", "Amb molts edificis i finestres hi ha centenars de peces. Proveu amb n petit i augmenteu-lo al final.|Con muchos edificios y ventanas hay cientos de piezas. Probad con n pequeño y aumentadlo al final."],
      ["Surt «el programa fa més de 400 peces».|Sale «el programa hace más de 400 piezas».", "És el límit del taller. Reduïu el nombre d'edificis o de finestres (per exemple, una finestra ampla per pis).|Es el límite del taller. Reducid el número de edificios o de ventanas (por ejemplo, una ventana ancha por piso)."],
      ["El botó de desar no s'activa.|El botón de guardar no se activa.", "Mireu quina comprovació és vermella: sovint és «cap dins de 120 × 120 mm» (el terrat sobresurt) o «una sola peça».|Mirad qué comprobación está en rojo: a menudo es «cabe dentro de 120 × 120 mm» (la azotea sobresale) o «una sola pieza»."]],
    extra: ["Ajuntar les illes de tota la classe en un sol programa amb un mòdul per alumne/a (com a OpenSCAD amb include).|Juntar las manzanas de toda la clase en un solo programa con un módulo por alumno/a (como en OpenSCAD con include).", "Afegir carrers, passos de vianants i un parc central amb un patró circular.|Añadir calles, pasos de peatones y un parque central con un patrón circular.", "Fer una fitxa tècnica de la illa: mòduls, paràmetres, mides i temps d'impressió estimat.|Hacer una ficha técnica de la manzana: módulos, parámetros, medidas y tiempo de impresión estimado."],
    trans: ["Unitat següent: enginyeria i fabricació (peces que encaixen i toleràncies).|Unidad siguiente: ingeniería y fabricación (piezas que encajan y tolerancias).", "Ciències socials: urbanisme, densitat i espais verds a la ciutat.|Ciencias sociales: urbanismo, densidad y espacios verdes en la ciudad."],
    slides: [
      { id: 's1', k: 'portada', t: 'Projecte: la ciutat modular|Proyecto: la ciudad modular', x: "Una illa del barri del futur, feta amb mòduls|Una manzana del barrio del futuro, hecha con módulos", nota: "Presenta l'exposició de l'Ajuntament i les illes de 120 × 120 mm.|Presenta la exposición del Ayuntamiento y las manzanas de 120 × 120 mm." },
      { id: 's2', k: 'pregunta', t: 'Prediu el carrer|Predice la calle', code: CK(`repeteix i de 0 a 2 {\n  mou(i * 30, 0, 0) edifici(3 - i)\n}`), nota: "3, 2 i 1 pisos: el carrer baixa.|3, 2 y 1 pisos: la calle baja." },
      { id: 's3', k: 'anim', t: 'El pla del projecte|El plan del proyecto', anim: 'p6plan', nota: "Si una prova falla, es torna al pas que toca.|Si una prueba falla, se vuelve al paso que toca." },
      { id: 's4', k: 'media', t: 'El mòdul edifici(pisos)|El módulo edificio(pisos)', media: { k: 'model', prog: B(EDIF1) }, nota: "Es prova sol amb tres crides abans de fer-lo servir a la illa.|Se prueba solo con tres llamadas antes de usarlo en la manzana." },
      { id: 's5', k: 'media', t: 'Un carrer amb un bucle|Una calle con un bucle', media: { k: 'model', prog: B(ROWC) }, nota: "edifici(2 + i): els pisos depenen del comptador.|edificio(2 + i): los pisos dependen del contador." },
      { id: 's6', k: 'media', t: 'La illa: bucles niats|La manzana: bucles anidados', media: { k: 'model', prog: B(BLOCK) }, nota: "9 edificis amb 3 línies d'escena. Pisos: 1 + i + j.|9 edificios con 3 líneas de escena. Pisos: 1 + i + j." },
      { id: 's7', k: 'media', t: 'Una variable per a tot el barri|Una variable para todo el barrio', media: { k: 'model', prog: B(BLOCKN) }, nota: "Les tres parts del programa. Amb n = 4, 16 edificis i una base de 160 mm (ja no cap a la illa!).|Las tres partes del programa. Con n = 4, 16 edificios y una base de 160 mm (¡ya no cabe en la manzana!)." },
      { id: 's8', k: 'activitat', t: "L'esbós de la teva illa|El boceto de tu manzana", timer: 7, punts: ["Vista de dalt a escala: 1 casella = 10 mm.|Vista de arriba a escala: 1 casilla = 10 mm.", "Llista de mòduls i paràmetres.|Lista de módulos y parámetros.", "Marca què es repeteix.|Marca qué se repite."], nota: "Individual, amb la fitxa del projecte.|Individual, con la ficha del proyecto." },
      { id: 's9', k: 'concepte', t: 'Comprovacions de fabricació|Comprobaciones de fabricación', punts: ["Una sola peça (tot sobre la base).|Una sola pieza (todo sobre la base).", "Cap dins de 120 × 120 mm.|Cabe dentro de 120 × 120 mm.", "Toca la placa i res no flota.|Toca la placa y nada flota."], nota: "Les mateixes comprovacions que farà la Nuvi abans d'imprimir.|Las mismas comprobaciones que hará la Nuvi antes de imprimir." },
      { id: 's10', k: 'repte', t: "A l'ordinador: pas a pas|En el ordenador: paso a paso", punts: ["1 · El mòdul.|1 · El módulo.", "2 · El carrer.|2 · La calle.", "3 · La illa.|3 · La manzana.", "4 · El barri paramètric.|4 · El barrio paramétrico."], nota: "Aquests passos són la plantilla del seu projecte.|Estos pasos son la plantilla de su proyecto." },
      { id: 's11', k: 'pregunta', t: 'Per què es trepitgen?|¿Por qué se pisan?', x: "Els edificis fan 20 mm i el pas és de 15. Quin pas deixaria un carrer de 20 mm?|Los edificios miden 20 mm y el paso es de 15. ¿Qué paso dejaría una calle de 20 mm?", nota: "Pas = amplada de l'edifici + carrer = 40 mm.|Paso = anchura del edificio + calle = 40 mm." },
      { id: 's12', k: 'concepte', t: 'Les tres parts, sempre|Las tres partes, siempre', punts: ["1 · Paràmetres del barri (n…).|1 · Parámetros del barrio (n…).", "2 · Mòduls amb comentaris.|2 · Módulos con comentarios.", "3 · L'escena amb bucles.|3 · La escena con bucles."], nota: "Que el seu projecte tingui les tres parts marcades amb comentaris.|Que su proyecto tenga las tres partes marcadas con comentarios." },
      { id: 's13', k: 'repte', t: 'La meva illa|Mi manzana', punts: ["Dos mòduls teus (un amb paràmetres).|Dos módulos tuyos (uno con parámetros).", "Bucles per al que es repeteix.|Bucles para lo que se repite.", "Una peça dins de 120 × 120 mm.|Una pieza dentro de 120 × 120 mm.", "Tres parts i comentaris.|Tres partes y comentarios."], nota: "Es desa a «Projectes» amb l'STL i el .scad.|Se guarda en «Proyectos» con el STL y el .scad." },
      { id: 's14', k: 'resum', t: 'Avui hem après…|Hoy hemos aprendido…', punts: ["Un projecte gran es planifica i es fa per passos.|Un proyecto grande se planifica y se hace por pasos.", "Mòduls + bucles + paràmetres = una ciutat.|Módulos + bucles + parámetros = una ciudad.", "Abans d'imprimir, comprovar.|Antes de imprimir, comprobar."], nota: "Llegiu-ho junts.|Leedlo juntos." },
      { id: 's15', k: 'tiquet', t: 'Tiquet de sortida|Ticket de salida', punts: ["Els passos del pla d'un projecte.|Los pasos del plan de un proyecto.", "n = 4: quants edificis?|n = 4: ¿cuántos edificios?"], nota: "Oral o en un paper.|Oral o en un papel." }
    ],
    print: [{ id: 'p1', t: "Fitxa del projecte: l'esbós de la illa|Ficha del proyecto: el boceto de la manzana", k: 'fitxa', intro: "La teva illa fa 120 × 120 mm. Al quadrat, cada casella fa 10 mm. Pensa-la abans de programar-la.|Tu manzana mide 120 × 120 mm. En el cuadrado, cada casilla mide 10 mm. Piénsala antes de programarla.",
      items: [{ q: "Dibuixa la vista de dalt de la teva illa en un quadrat de 12 × 12 caselles: edificis, carrers, places, arbres…|Dibuja la vista de arriba de tu manzana en un cuadrado de 12 × 12 casillas: edificios, calles, plazas, árboles…", big: true, sol: "Resposta oberta. Comproveu que res no surt del quadrat i que hi ha carrers entre els edificis.|Respuesta abierta. Comprobad que nada sale del cuadrado y que hay calles entre los edificios." },
        { q: "Llista de mòduls: nom, paràmetres (amb unitats) i què fa cada un. Almenys dos, i un amb paràmetres.|Lista de módulos: nombre, parámetros (con unidades) y qué hace cada uno. Al menos dos, y uno con parámetros.", big: true, sol: "Ex.: edifici(pisos): bloc de 20 × 20 × pisos × 10 mm; arbre(mida): tronc i copa.|Ej.: edificio(pisos): bloque de 20 × 20 × pisos × 10 mm; árbol(tamaño): tronco y copa." },
        { q: "Què es repeteix? Escriu els bucles que faràs servir (de quant a quant i amb quin pas).|¿Qué se repite? Escribe los bucles que usarás (de cuánto a cuánto y con qué paso).", sol: "Ex.: repeteix j de 0 a 2 { repeteix i de 0 a 2 { … } } amb pas 40.|Ej.: repite j de 0 a 2 { repite i de 0 a 2 { … } } con paso 40." },
        { q: "Quina variable faria canviar tot el barri? Què passaria si la dobles?|¿Qué variable haría cambiar todo el barrio? ¿Qué pasaría si la doblas?", sol: "Ex.: n (edificis per costat). Si es dobla, la base es fa el doble d'ampla i ja no cap a 120 mm.|Ej.: n (edificios por lado). Si se dobla, la base se hace el doble de ancha y ya no cabe en 120 mm." }] }]
  }
  };
})());
